export function GameDailyLoginRewardScreen() {
  const navigate = useNavigate();
  const location = useLocation();
  const rewardPasses = (location.state as DailyLoginRewardLocationState | null)?.rewardPasses;

  useEffect(() => {
    if (rewardPasses == null || rewardPasses <= 0) {
      navigate('/game/flight-tickets', { replace: true });
    }
  }, [rewardPasses, navigate]);

  if (rewardPasses == null || rewardPasses <= 0) {
    return null;
  }

  const goBack = () => {
    navigate('/game/flight-tickets');
  };

  return (
    <div style={root}>
      <header style={headerStrip}>
        <h2 style={titleOnHeader}>{t('game.flightTicket.dailyLoginSuccessTitle')}</h2>
      </header>
      <div style={body}>
        <div style={cardWrap}>
          <div style={card} role="region" aria-label={t('game.flightTicket.dailyLoginSuccessTitle')}>
            <img
              src={rewardsIcon}
              alt=""
              width={72}
              height={72}
              style={{ objectFit: 'contain' }}
            />
            <p style={rewardLine}>
              <span style={rewardBadge}>
                +{rewardPasses}
                <img src={coinIcon} alt="" width={18} height={18} style={{ objectFit: 'contain' }} />
              </span>
              <span>{t('game.flightTicket.dailyLoginRewardYours')}</span>
            </p>
            <div style={infoBox}>
              <p style={infoTitle}>{t('game.flightTicket.dailyLoginStreakTitle')}</p>
              <p style={bodyText}>{t('game.flightTicket.dailyLoginStreakBody')}</p>
              <p style={infoNote}>{t('game.flightTicket.dailyLoginStreakNote')}</p>
            </div>
          </div>
        </div>
      </div>
      <div style={footer}>
        <button type="button" style={actionBtn} onClick={goBack}>
          {t('game.flightTicket.dailyLoginBack')}
        </button>
      </div>
    </div>
  );
}
