import { useEffect, useMemo, useRef, useState } from 'react';
import type { CSSProperties, JSX } from 'react';
import { t } from '../../i18n';
import { buildClaudiStickers } from '../../application';
import type { ClaudiSticker } from '../../application';
import type { ClaudiStickerId } from '../../domain';
import { useAppStore } from '../store/appStore';
import commonBackground from '../../infrastructure/assets/Images/commonBackground.png';
import lobbyInteractArrow from '../../infrastructure/assets/Images/lobbyInteractArrow.png';
import { CLAUDI_STICKER_BG_BY_ID, CLAUDI_STICKER_IMAGE_BY_ID } from './claudiStickerAssets';
import {
  HeaderHintBackdrop,
  HeaderHintPopup,
  HeaderHintTitleButton,
  headerHintAnchor,
  headerHintTitleButton,
  useHeaderHintPopup,
} from './HeaderHintPopup';
import { useStickerGridLayout } from './useStickerGridLayout';

const root: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  overflow: 'hidden',
  color: '#1a1a1a',
  position: 'relative',
  backgroundImage: `url(${commonBackground})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  backgroundRepeat: 'no-repeat',
};

const body: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  overflow: 'hidden',
  padding: '8px 16px 4px',
  boxSizing: 'border-box',
  maxWidth: 520,
  width: '100%',
  margin: '0 auto',
};

const titleRow: CSSProperties = {
  flexShrink: 0,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  margin: '0 0 8px',
  ...headerHintAnchor,
};

const title: CSSProperties = {
  ...headerHintTitleButton,
  fontSize: 24,
  fontWeight: 900,
  color: '#1a1a1a',
};

const pageWrap: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  gap: 8,
  overflow: 'hidden',
};

const navBtn: CSSProperties = {
  flexShrink: 0,
  alignSelf: 'center',
  width: 44,
  height: 32,
  border: 'none',
  borderRadius: 12,
  cursor: 'pointer',
  background: 'rgba(88, 40, 140, 0.35)',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
};

const pageCounter: CSSProperties = {
  flexShrink: 0,
  margin: 0,
  textAlign: 'center',
  fontSize: 11,
  fontWeight: 800,
  color: '#5b1f84',
};

const emptyCell: CSSProperties = {
  borderRadius: 12,
  background: 'rgba(255,255,255,0.2)',
  border: '2px dashed rgba(90,30,120,0.18)',
  minHeight: 0,
  minWidth: 0,
};

function chunkStickers(stickers: ClaudiSticker[], pageSize: number): ClaudiSticker[][] {
  if (stickers.length === 0 || pageSize <= 0) {
    return [[]];
  }
  const pages: ClaudiSticker[][] = [];
  for (let i = 0; i < stickers.length; i += pageSize) {
    pages.push(stickers.slice(i, i + pageSize));
  }
  return pages;
}

function StickerCard({
  sticker,
  captionLines,
}: {
  sticker: ClaudiSticker;
  captionLines: number;
}): JSX.Element {
  const stickerId = sticker.id as ClaudiStickerId;
  const bg = CLAUDI_STICKER_BG_BY_ID[stickerId] ?? '#e0e0e0';
  const imageSrc = CLAUDI_STICKER_IMAGE_BY_ID[stickerId];
  const stickerCell: CSSProperties = {
    minWidth: 0,
    minHeight: 0,
    borderRadius: 12,
    overflow: 'hidden',
    boxShadow: '0 3px 10px rgba(0,0,0,0.1)',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'stretch',
    background: bg,
    opacity: sticker.unlocked ? 1 : 0.55,
    filter: sticker.unlocked ? undefined : 'grayscale(0.85)',
  };
  const stickerImageWrap: CSSProperties = {
    flex: 1,
    minHeight: 0,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 6,
    boxSizing: 'border-box',
  };
  const stickerImage: CSSProperties = {
    maxWidth: '70%',
    maxHeight: '70%',
    width: 'auto',
    height: 'auto',
    objectFit: 'contain',
  };
  const stickerCaption: CSSProperties = {
    flexShrink: 0,
    margin: 0,
    padding: '4px 6px 6px',
    fontSize: captionLines >= 3 ? 9 : 10,
    lineHeight: 1.2,
    fontWeight: 700,
    textAlign: 'center',
    color: '#1a1a1a',
    background: 'rgba(255,255,255,0.55)',
    display: '-webkit-box',
    WebkitLineClamp: captionLines,
    WebkitBoxOrient: 'vertical',
    overflow: 'hidden',
  };

  return (
    <div style={stickerCell} title={sticker.unlocked ? sticker.name : sticker.hint}>
      <div style={stickerImageWrap}>
        {imageSrc ? (
          <img src={imageSrc} alt="" style={stickerImage} />
        ) : (
          <span style={{ fontSize: 32 }} aria-hidden>
            {sticker.emoji}
          </span>
        )}
      </div>
      <p style={stickerCaption}>{sticker.name}</p>
    </div>
  );
}

function StickerGridPage({
  stickers,
  cols,
  rows,
  pageSize,
}: {
  stickers: ClaudiSticker[];
  cols: number;
  rows: number;
  pageSize: number;
}): JSX.Element {
  const slots = Array.from({ length: pageSize }, (_, i) => stickers[i] ?? null);
  const captionLines = rows >= 3 ? 2 : 3;
  const grid: CSSProperties = {
    flex: 1,
    minHeight: 0,
    display: 'grid',
    gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
    gridTemplateRows: `repeat(${rows}, minmax(0, 1fr))`,
    gap: 10,
  };

  return (
    <div style={grid} role="list" aria-label={t('game.rewards.claudiStickers')}>
      {slots.map((sticker, index) =>
        sticker ? (
          <StickerCard key={sticker.id} sticker={sticker} captionLines={captionLines} />
        ) : (
          <div key={`empty-${index}`} style={emptyCell} aria-hidden />
        ),
      )}
    </div>
  );
}

export function GameRewardsScreen() {
  const economy = useAppStore((s) => s.playerEconomy);
  const stickers = useMemo(() => buildClaudiStickers(economy), [economy]);
  const pageWrapRef = useRef<HTMLDivElement>(null);
  const [pageIndex, setPageIndex] = useState(0);
  const { hintOpen, toggleHint, closeHint } = useHeaderHintPopup();

  const layout = useStickerGridLayout(pageWrapRef, stickers.length);
  const pages = useMemo(
    () => chunkStickers(stickers, layout.pageSize),
    [stickers, layout.pageSize],
  );

  const pageCount = pages.length;
  const safePageIndex = pageCount > 0 ? pageIndex % pageCount : 0;
  const currentPage = pages[safePageIndex] ?? [];

  useEffect(() => {
    setPageIndex((i) => (pageCount > 0 ? i % pageCount : 0));
  }, [pageCount, layout.pageSize]);

  const goPrev = () => setPageIndex((i) => (i - 1 + pageCount) % pageCount);
  const goNext = () => setPageIndex((i) => (i + 1) % pageCount);

  const pageCounterLabel = t('game.rewards.pageCounter')
    .replace('{n}', String(safePageIndex + 1))
    .replace('{total}', String(pageCount));

  return (
    <div style={root}>
      {hintOpen ? <HeaderHintBackdrop onClose={closeHint} /> : null}
      <div style={body}>
        <div style={titleRow}>
          <HeaderHintTitleButton
            hintOpen={hintOpen}
            hintId="game-rewards-hint"
            onClick={toggleHint}
            style={title}
          >
            {t('game.rewards.title')}
          </HeaderHintTitleButton>
          {hintOpen ? (
            <HeaderHintPopup
              hintId="game-rewards-hint"
              hintTitle={t('game.rewards.infoTitle')}
              hintBody={t('game.rewards.infoBody')}
              onClose={closeHint}
            />
          ) : null}
        </div>

        <div ref={pageWrapRef} style={pageWrap}>
          <button type="button" style={navBtn} onClick={goPrev} aria-label={t('game.rewards.prevPage')}>
            <img src={lobbyInteractArrow} alt="" width={24} height={24} style={{ transform: 'rotate(-90deg)' }} />
          </button>

          <StickerGridPage
            stickers={currentPage}
            cols={layout.cols}
            rows={layout.rows}
            pageSize={layout.pageSize}
          />

          <button type="button" style={navBtn} onClick={goNext} aria-label={t('game.rewards.nextPage')}>
            <img src={lobbyInteractArrow} alt="" width={24} height={24} style={{ transform: 'rotate(90deg)' }} />
          </button>

          {pageCount > 1 ? <p style={pageCounter}>{pageCounterLabel}</p> : null}
        </div>
      </div>
    </div>
  );
}
