import { useCallback, useEffect, useRef, useState } from 'react';
import type { CSSProperties } from 'react';
import { t } from '../../i18n';

const DURATION_SEC = 60;
const ZONE_COUNT = 4;

type Props = {
  onWin: () => void;
  onLose: () => void;
};

const zoneStyle = (active: boolean, done: boolean): CSSProperties => ({
  flex: 1,
  minHeight: 72,
  margin: 4,
  border: '2px solid #333',
  borderRadius: 8,
  background: done ? '#6a6' : active ? '#bbb' : '#888',
  color: '#111',
  fontWeight: 700,
  fontSize: 14,
  cursor: done ? 'default' : 'pointer',
});

export function RockRepairGadgetPanel({ onWin, onLose }: Props) {
  const [nextIndex, setNextIndex] = useState(0);
  const [wrongCount, setWrongCount] = useState(0);
  const [remainingSec, setRemainingSec] = useState(DURATION_SEC);
  const endedRef = useRef(false);

  useEffect(() => {
    if (remainingSec <= 0) {
      if (!endedRef.current) {
        endedRef.current = true;
        onLose();
      }
      return;
    }
    const id = window.setInterval(() => {
      setRemainingSec((s) => s - 1);
    }, 1000);
    return () => window.clearInterval(id);
  }, [remainingSec, onLose]);

  const onZoneTap = useCallback(
    (index: number) => {
      if (index === nextIndex) {
        const n = nextIndex + 1;
        if (n >= ZONE_COUNT) {
          onWin();
        } else {
          setNextIndex(n);
        }
        return;
      }
      setWrongCount((w) => {
        const next = w + 1;
        if (next >= 3 && !endedRef.current) {
          endedRef.current = true;
          onLose();
        }
        return next;
      });
    },
    [nextIndex, onWin, onLose],
  );

  return (
    <div
      role="dialog"
      aria-label={t('shell.minigame.rock.title')}
      style={{
        position: 'absolute',
        inset: 0,
        background: 'rgba(0,0,0,0.75)',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 16,
        zIndex: 10,
        boxSizing: 'border-box',
      }}
    >
      <p style={{ color: '#fff', margin: '0 0 8px', fontWeight: 700 }}>
        {t('shell.minigame.rock.title')}
      </p>
      <p style={{ color: '#ddd', margin: '0 0 16px', fontSize: 14 }}>
        {t('shell.minigame.rock.hint').replace('{sec}', String(remainingSec))}
      </p>
      <p style={{ color: '#ddd', margin: '0 0 16px', fontSize: 13 }}>
        {`Ошибок: ${wrongCount}/3`}
      </p>
      <div style={{ display: 'flex', width: '100%', maxWidth: 400 }}>
        {Array.from({ length: ZONE_COUNT }, (_, i) => (
          <button
            key={i}
            type="button"
            disabled={i < nextIndex}
            style={zoneStyle(i === nextIndex, i < nextIndex)}
            onClick={() => onZoneTap(i)}
          >
            {i + 1}
          </button>
        ))}
      </div>
    </div>
  );
}
