import type { CSSProperties } from 'react';
import type { BoosterKind } from '../../domain';
import hpIcon from '../../infrastructure/assets/Images/hpIcon.png';
import { LEVEL_PROGRESS_HUD_BLOCK_PX } from './LevelProgressBar';
import { BOOSTER_HUD_ICON_BY_KIND } from './boosterHudIcons';
import { flightHudCentered } from './flightHudLayout';

const HP_ICON_PX = 32;
const BOOSTER_ICON_PX = 28;
const HUD_GAP_PX = 6;
const HEART_GAP_PX = 4;
const BOOSTER_ROW_GAP_PX = 4;

/** Потерянное сердце — тёмно-красный оттенок. */
const HEART_LOST_FILTER = 'brightness(0.5) sepia(1) hue-rotate(320deg) saturate(6)';
const HEART_HIT_FLASH_FILTER = 'brightness(0.38) sepia(1) hue-rotate(320deg) saturate(7)';

const livesHudBlock: CSSProperties = {
  ...flightHudCentered,
  top: `calc(max(8px, env(safe-area-inset-top)) + ${LEVEL_PROGRESS_HUD_BLOCK_PX}px + ${HUD_GAP_PX}px)`,
  zIndex: 10,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  gap: BOOSTER_ROW_GAP_PX,
  pointerEvents: 'none',
};

const livesRow: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: HEART_GAP_PX,
};

const boostersRow: CSSProperties = {
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: BOOSTER_ROW_GAP_PX,
};

const heartImg: CSSProperties = {
  width: HP_ICON_PX,
  height: HP_ICON_PX,
  objectFit: 'contain',
  flexShrink: 0,
  transition: 'filter 0.08s',
};

const boosterImg: CSSProperties = {
  width: BOOSTER_ICON_PX,
  height: BOOSTER_ICON_PX,
  objectFit: 'contain',
  flexShrink: 0,
};

export type LevelLivesHudProps = {
  /** Базовое число жизней курьера (иконок буфера). */
  maxLives: number;
  /** Засчитанные удары по буферу (0…maxLives). */
  strikes: number;
  /** Доп. жизни от бустера — отдельные иконки справа. */
  extraLifeCharges: number;
  /** Все базовые жизни исчерпаны — мини-игра. */
  minigameRequired: boolean;
  /** Краткая вспышка при новом ударе. */
  hitFlash: boolean;
  /** Активные собранные бустеры (иконки под жизнями). */
  activeBoosters?: readonly BoosterKind[];
};

export function LevelLivesHud({
  maxLives,
  strikes,
  extraLifeCharges,
  minigameRequired,
  hitFlash,
  activeBoosters = [],
}: LevelLivesHudProps) {
  const lostBaseHearts = minigameRequired ? maxLives : Math.min(maxLives, strikes);
  const totalHearts = maxLives + Math.max(0, extraLifeCharges);
  const hearts = Array.from({ length: totalHearts }, (_, i) => i);
  const livesRemaining = totalHearts - lostBaseHearts;

  const timedBoosters = activeBoosters.filter((k) => k !== 'extra_life');

  return (
    <div
      style={livesHudBlock}
      role="status"
      aria-live="polite"
      aria-label={String(livesRemaining)}
    >
      <div style={livesRow}>
        {hearts.map((index) => {
          const isLost = index < lostBaseHearts;
          const isLastLostOnFlash =
            hitFlash && isLost && index === lostBaseHearts - 1 && lostBaseHearts > 0;
          let filter: string | undefined;
          if (isLastLostOnFlash) {
            filter = HEART_HIT_FLASH_FILTER;
          } else if (isLost) {
            filter = HEART_LOST_FILTER;
          }
          return (
            <img
              key={index}
              src={hpIcon}
              alt=""
              style={{
                ...heartImg,
                filter,
              }}
            />
          );
        })}
      </div>
      {timedBoosters.length > 0 ? (
        <div style={boostersRow}>
          {timedBoosters.map((kind) => (
            <img
              key={kind}
              src={BOOSTER_HUD_ICON_BY_KIND[kind]}
              alt=""
              title={kind}
              style={boosterImg}
            />
          ))}
        </div>
      ) : null}
    </div>
  );
}
