const TIDY_RATING_THRESHOLD = 4.8;

export type StickerUnlockContext = {
  outcome: 'completed' | 'failed' | 'aborted';
  rating: number;
  sparksCollected: number;
  sparksTotal: number;
  isFirstSuccess: boolean;
  replayImproved: boolean;
  replayWorsened: boolean;
  collisionFree?: boolean;
  boosterUsedWithoutCollision?: boolean;
  finishedNearTimeLimit?: boolean;
  usedAllLives?: boolean;
  obstacleHitRatio?: number;
  noBoostersUsed?: boolean;
};

function normalizeStickerId(id: string): ClaudiStickerId | null {
  const mapped = LEGACY_CLAUDI_STICKER_IDS[id] ?? id;
  return CLAUDI_STICKERS.some((s) => s.id === mapped) ? (mapped as ClaudiStickerId) : null;
}

function hasSticker(state: PlayerEconomyState, id: ClaudiStickerId): boolean {
  return (state.stickers ?? []).some((s) => normalizeStickerId(s.id) === id);
}

function canUnlock(
  id: ClaudiStickerId,
  _state: PlayerEconomyState,
  ctx: StickerUnlockContext,
): boolean {
  if (ctx.outcome !== 'completed') {
    return false;
  }
  switch (id) {
    case 'claudi_first_success':
      return ctx.isFirstSuccess;
    case 'claudi_sweet_ride':
      return ctx.sparksTotal > 0 && ctx.sparksCollected >= ctx.sparksTotal;
    case 'claudi_nimble':
      return ctx.collisionFree === true;
    case 'claudi_boost_perfect':
      return ctx.boosterUsedWithoutCollision === true;
    case 'claudi_tidy':
      return ctx.rating >= TIDY_RATING_THRESHOLD;
    case 'claudi_second_chance':
      return ctx.replayImproved;
    case 'claudi_all_heroes':
      return false;
    case 'claudi_almost_late':
      return ctx.finishedNearTimeLimit === true;
    case 'claudi_sweet_diet':
      return ctx.sparksTotal > 0 && ctx.sparksCollected < ctx.sparksTotal * 0.5;
    case 'claudi_heartbreaker':
      return ctx.usedAllLives === true;
    case 'claudi_bumpy':
      return ctx.obstacleHitRatio != null && ctx.obstacleHitRatio >= 0.5;
    case 'claudi_worse_replay':
      return ctx.replayWorsened;
    case 'claudi_no_boost':
      return ctx.noBoostersUsed === true;
    default:
      return false;
  }
}

export function unlockClaudiStickers(
  state: PlayerEconomyState,
  ctx: StickerUnlockContext,
  now: number,
): { state: PlayerEconomyState; unlockedIds: ClaudiStickerId[] } {
  const unlockedIds: ClaudiStickerId[] = [];
  let stickers = [...(state.stickers ?? [])];
  for (const def of CLAUDI_STICKERS) {
    if (hasSticker({ ...state, stickers }, def.id)) {
      continue;
    }
    if (!canUnlock(def.id, { ...state, stickers }, ctx)) {
      continue;
    }
    stickers.push({ id: def.id, unlockedAt: now });
    unlockedIds.push(def.id);
  }
  return { state: { ...state, stickers }, unlockedIds };
}

export function isClaudiStickerUnlocked(state: PlayerEconomyState, id: ClaudiStickerId): boolean {
  return hasSticker(state, id);
}
