import { useRef, useState, type CSSProperties } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppStore } from '../store/appStore';
import { t } from '../../i18n';
import { COURIER_IDS, type CourierId } from '../../domain';
import startScreenBackground from '../../infrastructure/assets/Images/startScreenBackground.png';
import startScreenTextContainer from '../../infrastructure/assets/Images/startScreenTextContainer.png';
import actionButtonBackground from '../../infrastructure/assets/Images/actionButtonBackground.png';
import { COURIER_PORTRAIT_BY_ID } from './courierPortraits';

const shellBase: CSSProperties = {
  minHeight: '100dvh',
  boxSizing: 'border-box',
  padding: 'max(12px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(16px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left))',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'flex-start',
  backgroundColor: '#c8b6ff',
  backgroundImage: `url(${startScreenBackground})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center bottom',
  backgroundRepeat: 'no-repeat',
};

const textViolet = '#84388B';
const titleAccentGold = '#FDB813';

const textPanelStyle: CSSProperties = {
  marginTop: 24,
  width: 'min(92vw, 420px)',
  boxSizing: 'border-box',
  /** Вертикальные отступы: ещё +25% к 44/63 — выше «облако» startScreenTextContainer */
  padding: '55px 36px 79px',
  backgroundImage: `url(${startScreenTextContainer})`,
  backgroundSize: '100% 100%',
  backgroundRepeat: 'no-repeat',
  backgroundPosition: 'center',
  color: textViolet,
  textAlign: 'center',
};

const titleStyle: CSSProperties = {
  marginTop: 0,
  marginLeft: 0,
  marginRight: 0,
  marginBottom: 12,
  fontSize: 16,
  lineHeight: 1.25,
  fontWeight: 800,
  color: textViolet,
};

const bodyStyle: CSSProperties = {
  marginTop: 0,
  marginLeft: 0,
  marginRight: 0,
  marginBottom: 10,
  fontSize: 12,
  lineHeight: 1.45,
  color: textViolet,
};

/** Визуальный зазор между панелью с текстом и портретом курьера. */
const portraitSectionStyle: CSSProperties = {
  marginTop: 20,
  paddingTop: 16,
  width: '100%',
  maxWidth: 'min(92vw, 420px)',
  display: 'flex',
  justifyContent: 'center',
  boxSizing: 'border-box',
};

const characterPortraitStyle: CSSProperties = {
  marginTop: 0,
  maxWidth: 'min(253px, 82.8%)',
  width: '100%',
  height: 'auto',
  display: 'block',
  marginLeft: 'auto',
  marginRight: 'auto',
};

/** Как кнопка «Выбрать» на экране выбора курьера (`GameCharacterSelectScreen.selectBtn`). */
const actionButtonStyle: CSSProperties = {
  marginTop: 'auto',
  marginBottom: 8,
  width: 'min(49.5vw, 180px)',
  minHeight: 52,
  border: 'none',
  cursor: 'pointer',
  backgroundColor: 'transparent',
  backgroundImage: `url(${actionButtonBackground})`,
  backgroundSize: '100% 100%',
  color: '#fff',
  fontSize: 17,
  fontWeight: 900,
  textShadow: '0 1px 2px rgba(0,0,0,0.35)',
};

function pickRandomCourierId(): CourierId {
  const i = Math.floor(Math.random() * COURIER_IDS.length);
  return COURIER_IDS[i]!;
}

export function GameStartScreen() {
  const navigate = useNavigate();
  const completeOnboarding = useAppStore((s) => s.completeOnboarding);
  const [step, setStep] = useState(0);
  const randomCourierRef = useRef<CourierId | null>(null);
  if (randomCourierRef.current === null) {
    randomCourierRef.current = pickRandomCourierId();
  }
  const randomPortraitSrc = COURIER_PORTRAIT_BY_ID[randomCourierRef.current];

  const finishAndGoMap = () => {
    void (async () => {
      await completeOnboarding();
      navigate('/game/map', { replace: true });
    })();
  };

  return (
    <div style={shellBase}>
      <div
        style={{
          ...textPanelStyle,
          flex: '0 0 auto',
        }}
      >
        {step === 0 ? (
          <>
            <h1 style={{ ...titleStyle, marginBottom: 10 }}>
              <span style={{ display: 'block', color: textViolet }}>{t('shell.onboarding.step1.titleLine1')}</span>
              <span style={{ display: 'block', color: titleAccentGold, marginTop: 6 }}>
                {t('shell.onboarding.step1.titleLine2')}
              </span>
            </h1>
            <p style={bodyStyle}>{t('shell.onboarding.step1.p1')}</p>
            <p style={{ ...bodyStyle, marginBottom: 0 }}>{t('shell.onboarding.step1.p2')}</p>
          </>
        ) : (
          <>
            <h1 style={titleStyle}>{t('shell.onboarding.step2.title')}</h1>
            <p style={bodyStyle}>{t('shell.onboarding.step2.p1')}</p>
            <p style={{ ...bodyStyle, marginBottom: 0 }}>{t('shell.onboarding.step2.p2')}</p>
          </>
        )}
      </div>
      <div style={portraitSectionStyle}>
        <img
          src={randomPortraitSrc}
          alt=""
          decoding="async"
          style={characterPortraitStyle}
        />
      </div>

      <div style={{ flex: 1 }} />

      {step === 0 ? (
        <button type="button" style={actionButtonStyle} onClick={() => setStep(1)}>
          {t('shell.onboarding.step1.continue')}
        </button>
      ) : (
        <button type="button" style={actionButtonStyle} onClick={finishAndGoMap}>
          {t('shell.onboarding.step2.cta')}
        </button>
      )}
    </div>
  );
}
