import type { DeliveryOutcome } from '../deliveryRun/delivery';
import type { DeliveryRatingBreakdown } from '../rating/deliveryRating';
import type { MissionRef } from '../catalog/mission';
import { DELIVERY_ATTEMPTS_MAX } from './constants';
import type { DeliveryHistoryEntry, DeliveryHistoryOutcome, DeliveryPoolEntry, PlayerEconomyState } from './types';
import { deliveryIdFromMission } from './types';

export function isDeliveryAttempted(entry: DeliveryPoolEntry): boolean {
  return (
    entry.attemptsLeft < DELIVERY_ATTEMPTS_MAX ||
    entry.status === 'failed' ||
    entry.bestRating > 0
  );
}

export function isDeliveryHistorySuccess(entry: DeliveryHistoryEntry): boolean {
  return entry.bestRating > 0;
}

export function upsertDeliveryHistoryEntry(
  history: DeliveryHistoryEntry[],
  mission: MissionRef,
  outcome: DeliveryOutcome | 'aborted',
  rating: DeliveryRatingBreakdown,
  poolEntry: DeliveryPoolEntry,
  sparksCollected: number,
  sparksTotal: number,
  now: number,
): DeliveryHistoryEntry[] {
  const deliveryId = deliveryIdFromMission(mission);
  const historyOutcome: DeliveryHistoryOutcome = outcome === 'completed' ? 'completed' : 'failed';
  const existing = history.find((e) => e.deliveryId === deliveryId);

  const next: DeliveryHistoryEntry = {
    deliveryId,
    giantId: mission.giantId,
    orderIndex: mission.orderIndex,
    outcome: historyOutcome,
    bestRating: poolEntry.bestRating,
    lastRating: outcome === 'completed' ? rating : existing?.lastRating ?? null,
    lastSparksCollected: sparksCollected,
    lastSparksTotal: sparksTotal,
    updatedAt: now,
  };

  if (existing == null) {
    return [...history, next];
  }
  return history.map((e) => (e.deliveryId === deliveryId ? next : e));
}

/** Миграция старых сохранений: собрать историю из пула, если поле ещё пустое. */
export function migrateDeliveryHistory(state: PlayerEconomyState): PlayerEconomyState {
  if (Array.isArray(state.deliveryHistory) && state.deliveryHistory.length > 0) {
    return state;
  }
  const deliveryHistory = state.deliveryPool
    .filter(isDeliveryAttempted)
    .map((entry): DeliveryHistoryEntry => ({
      deliveryId: entry.deliveryId,
      giantId: entry.giantId,
      orderIndex: entry.orderIndex,
      outcome: entry.bestRating > 0 ? 'completed' : 'failed',
      bestRating: entry.bestRating,
      lastRating: null,
      lastSparksCollected: 0,
      lastSparksTotal: 0,
      updatedAt: entry.updatedAt,
    }));
  return { ...state, deliveryHistory };
}

export function listDeliveryHistorySorted(state: PlayerEconomyState): DeliveryHistoryEntry[] {
  const history = state.deliveryHistory ?? [];
  return [...history].sort((a, b) => b.updatedAt - a.updatedAt);
}
