import type { CourierId } from '../ids/ids';

/**
 * Параметры курьера в игре (GDD: скорость, управляемость, мощь).
 * Числа — относительные шкалы; маппинг в физику — в слое симуляции.
 */
export type CourierRunStats = {
  speed: number;
  handling: number;
  /** GDD «мощь»: размер персонажа и базовое число жизней-сердечек. */
  power: number;
};

/** Опорная скорость для нормализации к множителю к `baseForwardSpeed` уровня (середина шкалы GDD 3–10). */
const COURIER_SPEED_REFERENCE = 6;

const COURIER_STATS: Record<CourierId, CourierRunStats> = {
  eddy: { speed: 10, handling: 4, power: 2 },
  cloudy: { speed: 6, handling: 10, power: 4 },
  tucci: { speed: 3, handling: 6, power: 7 },
  ufo: { speed: 7, handling: 9, power: 3 },
  vall: { speed: 4, handling: 3, power: 10 },
  rock: { speed: 6, handling: 5, power: 9 },
};

export function getCourierRunStats(courierId: CourierId): CourierRunStats {
  return COURIER_STATS[courierId];
}

/**
 * Множитель «вперёд» от статы курьера: `effectiveBase ≈ level.baseForwardSpeed * это значение`.
 * Уточнить после плейтеста (tech-spec §6.2).
 */
export function getCourierForwardSpeedMultiplier(courierId: CourierId): number {
  return getCourierRunStats(courierId).speed / COURIER_SPEED_REFERENCE;
}

/**
 * Число жизней (засчитываемых столкновений) до мини-игры по стате «мощь».
 * Мощь 1–3 → 3; 4–6 → 4; 7–10 → 5.
 */
export function getCourierMaxLives(courierId: CourierId): number {
  const power = getCourierRunStats(courierId).power;
  if (power <= 3) {
    return 3;
  }
  if (power <= 6) {
    return 4;
  }
  return 5;
}

/** Нормализованная стата для UI-полос (0…1). */
export function getCourierStatBarValue(
  courierId: CourierId,
  stat: keyof CourierRunStats,
): number {
  return getCourierRunStats(courierId)[stat] / 10;
}
