/** @deprecated Используйте {@link GIANT_ORDERS}; строки — загадки заказов для UI. */
export const GIANT_ORDER_TEXTS = GIANT_IDS.reduce<Record<GiantId, readonly string[]>>(
  (acc, giantId) => {
    acc[giantId] = GIANT_ORDERS[giantId].map((order) => order.riddle);
    return acc;
  },
  {} as Record<GiantId, readonly string[]>,
);

function assertOrdersAlignWithDomain(): void {
  for (const g of GIANT_IDS) {
    const n = GIANT_ORDERS[g].length;
    const expected = GIANT_ORDER_COUNT[g];
    if (n !== expected) {
      throw new Error(
        `GIANT_ORDERS[${g}] has ${n} entries, GIANT_ORDER_COUNT expects ${expected}`,
      );
    }
  }
}

assertOrdersAlignWithDomain();

export function getGiantOrder(mission: MissionRef): GiantOrderDef {
  return GIANT_ORDERS[mission.giantId][mission.orderIndex];
}

/** Текст заказа по миссии — загадка гиганта (для UI). */
export function getGiantOrderText(mission: MissionRef): string {
  return getGiantOrder(mission).riddle;
}

/** Все заказы гиганта (копия для UI). */
export function getGiantOrders(giantId: GiantId): readonly GiantOrderDef[] {
  return GIANT_ORDERS[giantId];
}

/** @deprecated Используйте {@link getGiantOrders}. */
export function getGiantOrderTexts(giantId: GiantId): readonly string[] {
  return GIANT_ORDER_TEXTS[giantId];
}
