import { useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import type { CSSProperties } from 'react';
import { buildFlightTicketTasks } from '../../domain';
import { t } from '../../i18n';
import coinIcon from '../../infrastructure/assets/Images/coinIcon.png';
import commonBackground from '../../infrastructure/assets/Images/commonBackground.png';
import commonHeaderBackground from '../../infrastructure/assets/Images/commonHeaderBackground.png';
import lobbyInteractArrow from '../../infrastructure/assets/Images/lobbyInteractArrow.png';
import {
  HeaderHintBackdrop,
  HeaderHintPopup,
  HeaderHintTitleButton,
  headerHintAnchor,
  headerHintTitleButton,
  useHeaderHintPopup,
} from './HeaderHintPopup';
import { useAppStore } from '../store/appStore';

const isDev = process.env.NODE_ENV === 'development';

const root: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  textAlign: 'center',
  color: '#3a145c',
  position: 'relative',
  backgroundImage: `url(${commonBackground})`,
  backgroundSize: 'cover',
  backgroundPosition: 'center',
  backgroundRepeat: 'no-repeat',
};

const headerStrip: CSSProperties = {
  width: '100%',
  flexShrink: 0,
  marginTop: 3,
  paddingTop: 'max(8px, env(safe-area-inset-top))',
  backgroundImage: `url(${commonHeaderBackground})`,
  backgroundRepeat: 'no-repeat',
  backgroundSize: '100% 100%',
  backgroundPosition: 'center top',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  minHeight: 52,
  paddingBottom: 10,
  paddingLeft: 16,
  paddingRight: 16,
  boxSizing: 'border-box',
  gap: 6,
};

const titleWrap: CSSProperties = {
  ...headerHintAnchor,
  display: 'flex',
  justifyContent: 'center',
};

const titleOnHeader: CSSProperties = {
  ...headerHintTitleButton,
  fontSize: 22,
  fontWeight: 900,
  color: '#3a145c',
  textShadow: '0 1px 0 rgba(255,255,255,0.6)',
};

const earnedOnHeader: CSSProperties = {
  margin: 0,
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  gap: 8,
  fontSize: 14,
  fontWeight: 800,
  color: '#5b1f84',
};

const earnedBadge: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 6,
  fontSize: 14,
  fontWeight: 900,
  borderRadius: 999,
  padding: '4px 10px',
  color: '#5b1f84',
  background: '#f7d063',
  border: '2px solid rgba(90, 30, 120, 0.35)',
};

const body: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'stretch',
  justifyContent: 'flex-start',
  padding: '12px 8px',
  boxSizing: 'border-box',
};

const cardWrap: CSSProperties = {
  flex: 1,
  minHeight: 0,
  display: 'flex',
  alignItems: 'stretch',
  justifyContent: 'center',
  width: '100%',
  maxWidth: 520,
  margin: '0 auto',
};

const card: CSSProperties = {
  flex: 1,
  minWidth: 0,
  minHeight: 0,
  maxWidth: 460,
  width: '100%',
  padding: '12px 12px',
  borderRadius: 18,
  background: 'rgba(255, 255, 255, 0.82)',
  border: '3px solid rgba(90, 30, 120, 0.35)',
  fontSize: 14,
  lineHeight: 1.4,
  fontWeight: 700,
  overflowY: 'auto',
  WebkitOverflowScrolling: 'touch',
  textAlign: 'left',
};

const sectionTitle: CSSProperties = {
  margin: '0 0 8px',
  fontSize: 14,
  fontWeight: 900,
  color: '#5b1f84',
  textAlign: 'center',
};

const taskList: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  gap: 10,
  minHeight: 0,
};

const taskRow = (completed: boolean): CSSProperties => ({
  display: 'flex',
  flexDirection: 'row',
  alignItems: 'center',
  gap: 10,
  padding: '10px 10px',
  borderRadius: 14,
  border: `2px solid ${completed ? 'rgba(120,120,120,0.45)' : 'rgba(90, 30, 120, 0.35)'}`,
  background: completed ? 'rgba(200, 200, 200, 0.45)' : 'rgba(255, 255, 255, 0.9)',
  color: completed ? '#666' : '#3a145c',
  opacity: completed ? 0.75 : 1,
});

const actionBtn: CSSProperties = {
  width: 40,
  height: 40,
  border: 'none',
  borderRadius: 10,
  cursor: 'pointer',
  background: '#f7d063',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  flexShrink: 0,
};

const actionBtnDisabled: CSSProperties = {
  ...actionBtn,
  cursor: 'not-allowed',
  background: '#c8c8c8',
  opacity: 0.7,
};

const taskTitle: CSSProperties = {
  margin: 0,
  flex: 1,
  minWidth: 0,
  fontSize: 14,
  fontWeight: 800,
  lineHeight: 1.3,
  textAlign: 'left',
};

const rewardBadge: CSSProperties = {
  display: 'inline-flex',
  alignItems: 'center',
  gap: 4,
  padding: '4px 8px',
  borderRadius: 8,
  background: '#f7d063',
  border: '2px solid rgba(90, 30, 120, 0.25)',
  fontSize: 13,
  fontWeight: 900,
  color: '#5b1f84',
  flexShrink: 0,
};

const rewardBadgeCompleted: CSSProperties = {
  ...rewardBadge,
  background: '#d0d0d0',
  borderColor: 'rgba(120,120,120,0.35)',
  color: '#666',
};

export function GameFlightTicketScreen() {
  const navigate = useNavigate();
  const passesBalance = useAppStore((s) => s.passesBalance);
  const economy = useAppStore((s) => s.playerEconomy);
  const claimDailyLoginReward = useAppStore((s) => s.claimDailyLoginReward);
  const resetDailyLoginProgress = useAppStore((s) => s.resetDailyLoginProgress);
  const hydrationStatus = useAppStore((s) => s.hydrationStatus);
  const tasks = useMemo(() => buildFlightTicketTasks(economy), [economy]);

  useEffect(() => {
    if (hydrationStatus !== 'ready') {
      return;
    }
    const params = new URLSearchParams(window.location.search);
    if (isDev && params.get('resetDailyLogin') === '1') {
      void resetDailyLoginProgress().then(() => {
        params.delete('resetDailyLogin');
        const nextSearch = params.toString();
        const nextUrl = `${window.location.pathname}${nextSearch ? `?${nextSearch}` : ''}${window.location.hash}`;
        window.history.replaceState(null, '', nextUrl);
      });
    }
  }, [hydrationStatus, resetDailyLoginProgress]);

  const { hintOpen, toggleHint, closeHint } = useHeaderHintPopup();

  return (
    <div style={root}>
      {hintOpen ? <HeaderHintBackdrop onClose={closeHint} /> : null}
      <header style={headerStrip}>
        <div style={titleWrap}>
          <HeaderHintTitleButton
            hintOpen={hintOpen}
            hintId="game-flight-ticket-hint"
            onClick={toggleHint}
            style={titleOnHeader}
          >
            {t('game.flightTicket.title')}
          </HeaderHintTitleButton>
          {hintOpen ? (
            <HeaderHintPopup
              hintId="game-flight-ticket-hint"
              hintTitle={t('game.flightTicket.hintTitle')}
              hintBody={t('game.flightTicket.hintBody')}
              onClose={closeHint}
            />
          ) : null}
        </div>
        <p style={earnedOnHeader}>
          <span>{t('game.flightTicket.earned')}</span>
          <span style={earnedBadge}>
            {passesBalance}
            <img src={coinIcon} alt="" width={20} height={20} style={{ objectFit: 'contain' }} />
          </span>
        </p>
      </header>
      <div style={body}>
        <div style={cardWrap}>
          <div style={card} role="region" aria-label={t('game.flightTicket.currentTasks')}>
            <p style={sectionTitle}>{t('game.flightTicket.currentTasks')}</p>
            <div style={taskList}>
              {tasks.map((task) => {
                const completed = task.completed;
                const handleAction = () => {
                  if (!task.actionEnabled) {
                    return;
                  }
                  if (task.kind === 'daily_login') {
                    void claimDailyLoginReward().then((result) => {
                      if (!result.alreadyClaimed && result.rewardPasses > 0) {
                        navigate('/game/flight-tickets/daily-login-reward', {
                          state: { rewardPasses: result.rewardPasses },
                        });
                      }
                    });
                    return;
                  }
                  if (task.kind === 'quiz') {
                    navigate('/game/flight-tickets/quiz');
                  }
                };
                return (
                  <div key={task.id} style={taskRow(completed)}>
                    <p style={taskTitle}>{t(task.titleKey)}</p>
                    <span style={completed ? rewardBadgeCompleted : rewardBadge}>
                      +{task.rewardPasses}
                      <img src={coinIcon} alt="" width={16} height={16} style={{ objectFit: 'contain' }} />
                    </span>
                    <button
                      type="button"
                      style={task.actionEnabled ? actionBtn : actionBtnDisabled}
                      disabled={!task.actionEnabled}
                      aria-label={t(task.titleKey)}
                      onClick={handleAction}
                    >
                      <img src={lobbyInteractArrow} alt="" width={22} height={22} />
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
