import ru from './ru.json';

type JsonRecord = Record<string, unknown>;

function walk(root: unknown, parts: readonly string[]): unknown {
  let cur: unknown = root;
  for (const p of parts) {
    if (cur == null || typeof cur !== 'object') {
      return undefined;
    }
    cur = (cur as JsonRecord)[p];
  }
  return cur;
}

/**
 * Строка по пути вида `shell.home.title` из `ru.json` (tech-spec §9).
 * Если ключа нет — возвращает сам путь (удобно заметить в QA).
 */
export function t(path: string): string {
  const value = walk(ru, path.split('.'));
  return typeof value === 'string' ? value : path;
}
