import type { BoosterKind, LevelDefinition } from '../../domain';

export type LevelBoosterSpawnEntry = {
  segmentIndex: number;
  spawnIndex: number;
  s: number;
  lane: number;
  type: BoosterKind;
};

/** Все спавны бустеров уровня, по возрастанию `s` (и стабильный вторичный ключ). */
export function listLevelBoosterSpawnsSorted(level: LevelDefinition): LevelBoosterSpawnEntry[] {
  const out: LevelBoosterSpawnEntry[] = [];
  for (let si = 0; si < level.segments.length; si++) {
    const seg = level.segments[si];
    if (!seg.boosters) {
      continue;
    }
    for (let bi = 0; bi < seg.boosters.length; bi++) {
      const b = seg.boosters[bi];
      out.push({ segmentIndex: si, spawnIndex: bi, s: b.s, lane: b.lane, type: b.type });
    }
  }
  out.sort(
    (a, b) => a.s - b.s || a.segmentIndex - b.segmentIndex || a.spawnIndex - b.spawnIndex,
  );
  return out;
}
