import type { CSSProperties } from 'react';
import levelTimerIcon from '../../infrastructure/assets/Images/levelTimerIcon.png';
import finishFlagIcon from '../../infrastructure/assets/Images/finishFlagIcon.png';
import skillBarBg from '../../infrastructure/assets/Images/skillValueBarBackground.png';
import skillBarFill from '../../infrastructure/assets/Images/skillValueScale.png';
import { flightHudCentered } from './flightHudLayout';

const BAR_HEIGHT_PX = 26;
const TIMER_ICON_PX = 52;
const FLAG_ICON_PX = 48;

/** Высота блока прогресс-бара (для позиционирования HUD ниже). */
export const LEVEL_PROGRESS_HUD_BLOCK_PX = TIMER_ICON_PX;

const hudRow: CSSProperties = {
  ...flightHudCentered,
  top: 'max(8px, env(safe-area-inset-top))',
  zIndex: 10,
  display: 'flex',
  alignItems: 'center',
  gap: 0,
  pointerEvents: 'none',
};

const timerImg: CSSProperties = {
  width: TIMER_ICON_PX,
  height: TIMER_ICON_PX,
  flexShrink: 0,
  objectFit: 'contain',
  marginRight: -10,
  zIndex: 2,
};

const flagImg: CSSProperties = {
  width: FLAG_ICON_PX,
  height: FLAG_ICON_PX,
  flexShrink: 0,
  objectFit: 'contain',
  marginLeft: -6,
  zIndex: 2,
};

const barTrack: CSSProperties = {
  flex: 1,
  minWidth: 0,
  height: BAR_HEIGHT_PX,
  borderRadius: 999,
  backgroundImage: `url(${skillBarBg})`,
  backgroundSize: '100% 100%',
  backgroundRepeat: 'no-repeat',
  position: 'relative',
  overflow: 'hidden',
};

const labelBase: CSSProperties = {
  position: 'absolute',
  top: '50%',
  transform: 'translateY(-50%)',
  fontSize: 14,
  fontWeight: 800,
  color: '#fff',
  textShadow: '0 1px 2px rgba(0,0,0,0.45)',
  whiteSpace: 'nowrap',
  lineHeight: 1,
};

function formatHudSeconds(sec: number): string {
  return `${Math.max(0, Math.floor(sec))}с`;
}

function formatHudMeters(m: number): string {
  return `${Math.max(0, m).toFixed(1).replace('.', ',')}м`;
}

export type LevelProgressBarProps = {
  /** Игровое время мира, сек. */
  elapsedSec: number;
  /** Оставшийся путь до финиша, м (единицы `s` маршрута). */
  distanceFromFinishM: number;
  /** Доля пройденного маршрута 0…1. */
  routeProgress: number;
};

export function LevelProgressBar({
  elapsedSec,
  distanceFromFinishM,
  routeProgress,
}: LevelProgressBarProps) {
  const pct = Math.min(1, Math.max(0, routeProgress)) * 100;
  const timeLabel = formatHudSeconds(elapsedSec);
  const distanceLabel = formatHudMeters(distanceFromFinishM);

  return (
    <div style={hudRow} role="group" aria-label={timeLabel}>
      <img src={levelTimerIcon} alt="" style={timerImg} />
      <div style={barTrack}>
        <img
          src={skillBarFill}
          alt=""
          style={{
            position: 'absolute',
            left: 0,
            top: 0,
            height: '100%',
            width: `${pct}%`,
            objectFit: 'fill',
            objectPosition: 'left center',
          }}
        />
        <span
          style={{
            ...labelBase,
            left: 10,
          }}
        >
          {timeLabel}
        </span>
        <span
          style={{
            ...labelBase,
            right: 10,
          }}
        >
          {distanceLabel}
        </span>
      </div>
      <img src={finishFlagIcon} alt="" style={flagImg} />
    </div>
  );
}
