import type { CSSProperties, ReactNode } from 'react';
import type { GiantId } from '../../domain';
import markerDefault from '../../infrastructure/assets/Images/defaultDeliveryNotificationBackground.png';
import markerUrgent from '../../infrastructure/assets/Images/fastDeliveryNotificationBackground.png';
import { GIANT_PORTRAIT_BY_ID, GIANT_PORTRAIT_DISPLAY_PX } from './giantPortraits';

export const MAP_DELIVERY_POPUP_W_PX = 135;
export const MAP_DELIVERY_POPUP_H_PX = 105;

const deliveryCaptionStyle: CSSProperties = {
  position: 'absolute',
  left: '50%',
  top: 'calc(50% - 15px)',
  transform: 'translate(-50%, -50%)',
  padding: '2px 1px',
  background: 'transparent',
  color: '#E8AB27',
  fontSize: 14.25,
  fontWeight: 700,
  lineHeight: 1.1,
  textTransform: 'lowercase',
  pointerEvents: 'none',
  whiteSpace: 'pre-line',
  textAlign: 'center',
};

const giantPortraitStyle: CSSProperties = {
  width: GIANT_PORTRAIT_DISPLAY_PX,
  height: GIANT_PORTRAIT_DISPLAY_PX,
  objectFit: 'contain',
  flexShrink: 0,
  pointerEvents: 'none',
};

export type GiantMapMarkerProps = {
  giantId: GiantId;
  urgent: boolean;
  important?: boolean;
  waitingDay?: number;
  locked?: boolean;
  caption: string;
  onClick: () => void;
  ariaLabel: string;
};

function captionColor(urgent: boolean, important: boolean, waitingDay: number): string {
  if (urgent) {
    if (waitingDay >= 3) {
      return '#c41e1e';
    }
    if (waitingDay >= 2) {
      return '#e03030';
    }
    return '#E8AB27';
  }
  if (important) {
    return waitingDay >= 2 ? '#d03010' : '#d45a20';
  }
  return '#E8AB27';
}

export function GiantMapMarker({
  giantId,
  urgent,
  important = false,
  waitingDay = 1,
  locked = false,
  caption,
  onClick,
  ariaLabel,
}: GiantMapMarkerProps) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={ariaLabel}
      style={{
        position: 'absolute',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        border: 'none',
        padding: 0,
        cursor: locked ? 'not-allowed' : 'pointer',
        background: 'transparent',
        opacity: locked ? 0.45 : 1,
        filter: locked ? 'grayscale(0.85)' : undefined,
      }}
    >
      <div
        style={{
          position: 'relative',
          width: MAP_DELIVERY_POPUP_W_PX,
          height: MAP_DELIVERY_POPUP_H_PX,
        }}
      >
        <img
          src={urgent ? markerUrgent : markerDefault}
          alt=""
          style={{ width: '100%', height: '100%', objectFit: 'contain' }}
        />
        <span
          aria-hidden="true"
          style={{
            ...deliveryCaptionStyle,
            fontSize: caption.length > 28 ? 10 : 12,
            lineHeight: 1.15,
            textTransform: 'none',
            maxWidth: MAP_DELIVERY_POPUP_W_PX - 12,
            color: captionColor(urgent, important, waitingDay),
          }}
        >
          {caption}
        </span>
      </div>
      <img src={GIANT_PORTRAIT_BY_ID[giantId]} alt="" style={{ ...giantPortraitStyle, marginTop: 2 }} />
      {locked ? (
        <span
          aria-hidden
          style={{
            position: 'absolute',
            bottom: 0,
            right: -4,
            width: 22,
            height: 22,
            borderRadius: 999,
            background: 'rgba(30,30,30,0.85)',
            color: '#fff',
            fontSize: 12,
            fontWeight: 900,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          🔒
        </span>
      ) : null}
    </button>
  );
}

const finishBubbleStyle: CSSProperties = {
  position: 'relative',
  minWidth: 120,
  maxWidth: 200,
  padding: '10px 14px',
  borderRadius: 14,
  background: 'rgba(255, 252, 240, 0.95)',
  color: '#3d2060',
  fontSize: 16,
  fontWeight: 700,
  lineHeight: 1.2,
  textAlign: 'center',
  boxShadow: '0 4px 12px rgba(0,0,0,0.25)',
  pointerEvents: 'none',
};

const finishBubbleTailStyle: CSSProperties = {
  position: 'absolute',
  bottom: -8,
  left: '50%',
  transform: 'translateX(-50%)',
  width: 0,
  height: 0,
  borderLeft: '10px solid transparent',
  borderRight: '10px solid transparent',
  borderTop: '10px solid rgba(255, 252, 240, 0.95)',
};

export type LevelFinishGiantProps = {
  giantId: GiantId;
  speech: string;
  footer?: ReactNode;
};

export function LevelFinishGiant({ giantId, speech, footer }: LevelFinishGiantProps) {
  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 8,
        pointerEvents: 'auto',
      }}
    >
      <div style={finishBubbleStyle}>
        {speech}
        <span aria-hidden style={finishBubbleTailStyle} />
      </div>
      <img src={GIANT_PORTRAIT_BY_ID[giantId]} alt="" style={giantPortraitStyle} />
      {footer}
    </div>
  );
}

/** Высота стека «попап + портрет» для расчёта границ маркера на карте. */
export function mapMarkerStackHeightPx(): number {
  return MAP_DELIVERY_POPUP_H_PX + 2 + GIANT_PORTRAIT_DISPLAY_PX;
}
