import { isTerminal } from '../../domain';
import type { GameSession } from './GameSession';
import { applyBoosterPickupToSession } from './boosterPickup';
import type { LevelBoosterSpawnEntry } from './levelBoosters';
import { listLevelBoosterSpawnsSorted } from './levelBoosters';
import { getLevelRouteEndS } from './runRoute';

export type FlightRunProgress = {
  /** Игровое время мира сессии, сек (см. {@link GameSession.getWorldTimeSec}). */
  elapsedWorldTimeSec: number;
  /** Пройденная дистанция вдоль маршрута в единицах `s` уровня. */
  distanceAlongRouteS: number;
  /** Длина маршрута (конечный `s`). */
  routeEndS: number;
  /** Оставшийся путь до финиша: `routeEndS - distanceAlongRouteS`, не ниже 0. */
  distanceFromFinishS: number;
};

export type FlightRunControllerOptions = {
  /** Фиксированный шаг симуляции, сек (например 1/60). */
  fixedStepSec: number;
  /** Защита от спирали при большом `realDeltaSec`. */
  maxStepsPerFrame: number;
  /** Подбирать бустеры по пересечению `s` с маршрутом (по умолчанию включено). */
  pickupBoosters: boolean;
};

const DEFAULT_OPTIONS: FlightRunControllerOptions = {
  fixedStepSec: 1 / 60,
  maxStepsPerFrame: 24,
  pickupBoosters: true,
};

/**
 * Тик полёта: копит реальное время, шагает сессию фиксированными шагами,
 * интегрирует пройденный `s` как `baseForwardSpeed * effectiveMultiplier * dt`.
 */
export class FlightRunController {
  private accumulatorSec = 0;
  private distanceAlongRouteS = 0;
  private readonly routeEndS: number;
  private readonly options: FlightRunControllerOptions;
  private readonly boosterSpawns: readonly LevelBoosterSpawnEntry[];
  private readonly collectedBoosterKeys = new Set<string>();
  /** Первый шаг симуляции: нижняя граница интервала по `s` — −∞, чтобы подобрать бустер на `s === 0`. */
  private boosterSweepNeedsNegativeInfLow = true;

  constructor(
    private readonly session: GameSession,
    options: Partial<FlightRunControllerOptions> = {},
  ) {
    this.routeEndS = getLevelRouteEndS(session.level);
    this.options = { ...DEFAULT_OPTIONS, ...options };
    this.boosterSpawns = listLevelBoosterSpawnsSorted(session.level);
  }

  getRouteEndS(): number {
    return this.routeEndS;
  }

  getDistanceAlongRouteS(): number {
    return this.distanceAlongRouteS;
  }

  getProgress(): FlightRunProgress {
    const routeEndS = this.routeEndS;
    const distanceFromFinishS = Math.max(0, routeEndS - this.distanceAlongRouteS);
    return {
      elapsedWorldTimeSec: this.session.getWorldTimeSec(),
      distanceAlongRouteS: this.distanceAlongRouteS,
      routeEndS,
      distanceFromFinishS,
    };
  }

  private boosterKey(entry: LevelBoosterSpawnEntry): string {
    return `${entry.segmentIndex}:${entry.spawnIndex}`;
  }

  /**
   * Движение вперёд по `s`: подобрать все бустеры в интервале
   * `(lowExclusive, highInclusive]` по дистанции вдоль маршрута.
   */
  private collectBoostersCrossed(lowExclusive: number, highInclusive: number): void {
    if (!this.options.pickupBoosters) {
      return;
    }
    for (const b of this.boosterSpawns) {
      const key = this.boosterKey(b);
      if (this.collectedBoosterKeys.has(key)) {
        continue;
      }
      if (b.s > lowExclusive && b.s <= highInclusive) {
        this.collectedBoosterKeys.add(key);
        applyBoosterPickupToSession(this.session, b.type);
      }
    }
  }

  /**
   * Один кадр: накапливает `realDeltaSec`, выполняет целые шаги `fixedStepSec`.
   * При паузе сессии или терминальном `deliveryRun` время и дистанция не двигаются.
   */
  tickFrame(realDeltaSec: number): void {
    if (!Number.isFinite(realDeltaSec) || realDeltaSec < 0) {
      throw new Error('FlightRunController.tickFrame: realDeltaSec must be a non-negative finite number');
    }
    if (this.session.isPaused() || isTerminal(this.session.getDeliveryRun())) {
      return;
    }
    this.accumulatorSec += realDeltaSec;
    const { fixedStepSec, maxStepsPerFrame } = this.options;
    let steps = 0;
    while (this.accumulatorSec >= fixedStepSec && steps < maxStepsPerFrame) {
      const sBefore = this.distanceAlongRouteS;
      this.session.advanceWorldTime(fixedStepSec);
      const ds =
        this.session.level.baseForwardSpeed *
        this.session.getEffectiveForwardSpeedMultiplier() *
        fixedStepSec;
      const sAfter = Math.min(this.routeEndS, sBefore + ds);
      const lowExclusive = this.boosterSweepNeedsNegativeInfLow ? Number.NEGATIVE_INFINITY : sBefore;
      this.boosterSweepNeedsNegativeInfLow = false;
      this.collectBoostersCrossed(lowExclusive, sAfter);
      this.distanceAlongRouteS = sAfter;
      this.accumulatorSec -= fixedStepSec;
      steps += 1;
    }
  }
}
