import { useEffect } from 'react';
import { Navigate, Route, Routes } from 'react-router-dom';
import { useAppStore } from './store/appStore';
import { t } from '../i18n';
import { CourierSelectScreen } from './screens/CourierSelectScreen';
import { HomeHubScreen } from './screens/HomeHubScreen';
import { GameplayScreen } from './screens/GameplayScreen';
import { MissionBriefScreen } from './screens/MissionBriefScreen';
import { MissionCatalogScreen } from './screens/MissionCatalogScreen';
import { ResultScreen } from './screens/ResultScreen';
import { GameStartScreen } from './game/GameStartScreen';
import { GameHubLayout } from './game/GameHubLayout';
import { GameMapScreen } from './game/GameMapScreen';
import { GameDeliveriesScreen } from './game/GameDeliveriesScreen';
import { GameRewardsScreen } from './game/GameRewardsScreen';
import { GameFlightTicketScreen } from './game/GameFlightTicketScreen';
import { GameQuizScreen } from './game/GameQuizScreen';
import { GameDailyLoginRewardScreen } from './game/GameDailyLoginRewardScreen';
import { GameProfileScreen } from './game/GameProfileScreen';
import { GameRatingScreen } from './game/GameRatingScreen';
import { GameLicenseScreen } from './game/GameLicenseScreen';
import { GameCharacterSelectScreen } from './game/GameCharacterSelectScreen';

function SplashScreen() {
  return (
    <div style={{ padding: 24 }}>
      <p>{t('shell.splash.loading')}</p>
    </div>
  );
}

function BootstrapErrorScreen() {
  const error = useAppStore((s) => s.hydrationError);
  const bootstrap = useAppStore((s) => s.bootstrap);
  return (
    <div style={{ padding: 24 }}>
      <p>{t('shell.bootstrapError.title')}</p>
      {error != null && error !== '' ? (
        <pre style={{ whiteSpace: 'pre-wrap', fontSize: 12 }}>{error}</pre>
      ) : null}
      <button type="button" onClick={() => void bootstrap()}>
        {t('shell.bootstrapError.retry')}
      </button>
    </div>
  );
}

function RootRedirect() {
  const onboardingComplete = useAppStore((s) => s.onboardingComplete);
  if (!onboardingComplete) {
    return <Navigate to="/game/start" replace />;
  }
  return <Navigate to="/game/map" replace />;
}

const DEV_DAILY_LOGIN_SEED_KEY = 'delivery_vk_daily_login_seed_streak4_v4';

function useDevDailyLoginSeed(): void {
  const status = useAppStore((s) => s.hydrationStatus);
  const seedDailyLoginStreakForDev = useAppStore((s) => s.seedDailyLoginStreakForDev);

  useEffect(() => {
    if (process.env.NODE_ENV !== 'development' || status !== 'ready') {
      return;
    }
    if (sessionStorage.getItem(DEV_DAILY_LOGIN_SEED_KEY) === '1') {
      return;
    }
    sessionStorage.setItem(DEV_DAILY_LOGIN_SEED_KEY, '1');
    void seedDailyLoginStreakForDev(4);
  }, [status, seedDailyLoginStreakForDev]);
}

export function AppShell() {
  const status = useAppStore((s) => s.hydrationStatus);
  const bootstrap = useAppStore((s) => s.bootstrap);

  useEffect(() => {
    void bootstrap();
  }, [bootstrap]);

  useDevDailyLoginSeed();

  if (status === 'loading') {
    return <SplashScreen />;
  }
  if (status === 'error') {
    return <BootstrapErrorScreen />;
  }

  return (
    <Routes>
      <Route path="/" element={<RootRedirect />} />
      <Route path="/onboarding/1" element={<Navigate to="/game/start" replace />} />
      <Route path="/onboarding/2" element={<Navigate to="/game/start" replace />} />
      <Route path="/game/start" element={<GameStartScreen />} />
      <Route path="/game" element={<GameHubLayout />}>
        <Route index element={<Navigate to="/game/map" replace />} />
        <Route path="map" element={<GameMapScreen />} />
        <Route path="deliveries" element={<GameDeliveriesScreen />} />
        <Route path="rewards" element={<GameRewardsScreen />} />
        <Route path="flight-tickets" element={<GameFlightTicketScreen />} />
        <Route path="flight-tickets/quiz" element={<GameQuizScreen />} />
        <Route path="flight-tickets/daily-login-reward" element={<GameDailyLoginRewardScreen />} />
        <Route path="profile" element={<GameProfileScreen />} />
        <Route path="rating" element={<GameRatingScreen />} />
        <Route path="license" element={<GameLicenseScreen />} />
        <Route path="character/:giantId?" element={<GameCharacterSelectScreen />} />
      </Route>
      <Route path="/courier" element={<CourierSelectScreen />} />
      <Route path="/home" element={<HomeHubScreen />} />
      <Route path="/missions" element={<MissionCatalogScreen />} />
      <Route path="/mission/:giantId/:orderIndex" element={<MissionBriefScreen />} />
      <Route path="/play" element={<GameplayScreen />} />
      <Route path="/result" element={<ResultScreen />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}
