/**
 * Бустеры: единые для всех уровней (GDD).
 * Подбор активирует эффект сразу + анимация вокруг курьера.
 */
export const BOOSTER_KINDS = ['shield', 'speed', 'resize_shrink', 'extra_life'] as const;

export type BoosterKind = (typeof BOOSTER_KINDS)[number];

/** Длительность эффекта бустеров «Защита» и «Ускоритель», сек (GDD). */
export const BOOSTER_EFFECT_DURATION_SEC = 15 as const;

/** Множитель скорости для бустера «Ускоритель» (GDD: ×1,3). */
export const BOOSTER_SPEED_MULTIPLIER = 1.3 as const;

/**
 * Множитель к размеру хитбокса при бустере «уменьшение» (баланс до плейтеста).
 * Симуляция умножает базовый радиус курьера на это значение, пока эффект активен.
 */
export const BOOSTER_SHRINK_HITBOX_MULTIPLIER = 0.75 as const;
