export type DeliveryResultModalProps = {
  mission: MissionRef | null;
  outcome: DeliveryOutcome | 'aborted';
  rating: DeliveryRatingBreakdown | null;
  sparksCollected: number;
  sparksTotal: number;
  onRetry?: () => void;
  onToHub: () => void;
};

export type DeliveryResultStatRows = {
  speed: string;
  sparks: string;
  agility: string;
  orderRating: string;
};

export function buildDeliveryResultStatRows(
  rating: DeliveryRatingBreakdown | null,
  sparksCollected: number,
  sparksTotal: number,
): DeliveryResultStatRows {
  if (rating == null) {
    return {
      speed: '—',
      sparks: '—',
      agility: '—',
      orderRating: '—',
    };
  }
  return {
    speed: `${Math.round((rating.timeScore / 2) * 10)} из 10`,
    sparks: `${sparksCollected} из ${sparksTotal}`,
    agility: `${Math.round(rating.skillScore * 6)} из 6`,
    orderRating: `${rating.totalScore.toFixed(1).replace('.', ',')} из 5`,
  };
}

