export function DeliveryResultModal({
  mission: _mission,
  outcome,
  rating,
  sparksCollected,
  sparksTotal,
  onRetry,
  onToHub,
}: DeliveryResultModalProps) {
  const success = outcome === 'completed';
  const modalTitle = success ? t('shell.result.successTitle') : t('shell.result.failTitle');
  const statRows = buildDeliveryResultStatRows(rating, sparksCollected, sparksTotal);

  return (
    <div role="dialog" aria-modal="true" aria-label={modalTitle} style={overlay}>
      <header style={headerStrip}>
        <h2 style={titleOnHeader}>{modalTitle}</h2>
      </header>

      <div style={body}>
        <div style={cardWrap}>
          <div style={card}>
            {success ? (
              <>
                <img
                  src={rewardsIcon}
                  alt=""
                  width={64}
                  height={64}
                  style={{ objectFit: 'contain' }}
                />
                <p style={subtitle}>{t('shell.result.yourResult')}</p>
                <div style={statRow}>
                  <span style={statLabel}>
                    {t('game.character.statSpeed')}
                    <img src={speedIcon} alt="" width={22} height={22} style={{ objectFit: 'contain' }} />
                  </span>
                  <span>{statRows.speed}</span>
                </div>
                <div style={statRow}>
                  <span style={statLabel}>
                    {t('shell.result.sparksLabel')}
                    <img src={rewardsIcon} alt="" width={22} height={22} style={{ objectFit: 'contain' }} />
                  </span>
                  <span>{statRows.sparks}</span>
                </div>
                <div style={statRow}>
                  <span style={statLabel}>
                    {t('shell.result.agilityLabel')}
                    <img src={controlIcon} alt="" width={22} height={22} style={{ objectFit: 'contain' }} />
                  </span>
                  <span>{statRows.agility}</span>
                </div>
                <div style={ratingRow}>
                  <span style={statLabel}>
                    {t('game.deliveries.orderRating')}
                    <img src={rewardsIcon} alt="" width={22} height={22} style={{ objectFit: 'contain' }} />
                  </span>
                  <span>{statRows.orderRating}</span>
                </div>
              </>
            ) : (
              <p style={failBox}>{t('shell.result.failBody')}</p>
            )}
          </div>
        </div>
      </div>

      <div style={footer}>
        {onRetry != null ? (
          <>
            <button type="button" style={actionBtn} onClick={onRetry}>
              {t('shell.result.retry')}
            </button>
            <div style={passCostRow}>
              <span>{t('shell.result.spendPasses')}</span>
              <span style={passBadge}>
                {REPLAY_PASS_COST}
                <img src={coinIcon} alt="" width={18} height={18} style={{ objectFit: 'contain' }} />
              </span>
            </div>
          </>
        ) : null}
        <button type="button" style={actionBtn} onClick={onToHub}>
          {t('shell.result.toHub')}
        </button>
      </div>
    </div>
  );
}
