import {
  GIANT_LEVEL_ID_SUFFIX,
  MODIFIER_DURATION_SEC,
  getModifierForGiant,
  type GiantId,
  type LevelDefinition,
} from '../../domain';
import { GIANT_LEVEL_OBSTACLES } from './giantLevelObstacles';

const GIANT_VISUAL_THEME: Record<GiantId, string> = {
  swami: 'royal_hill',
  rose_observatory: 'mountain_observatory',
  drakocha: 'boiling_lake',
  yeti: 'ice_plains',
  mona: 'foam_sea',
  captain_duck: 'golden_bay',
  serge: 'north_cove',
  factor: 'techno_desert',
  sol: 'bright_sky',
  luna_mu: 'dark_sky',
  haunted_house: 'dark_manor',
  uncle_willy: 'willy_estate',
};

const BOOSTER_LAYOUT = [
  { s: 4.25, lane: 0.08, type: 'shield' as const },
  { s: 15, lane: 0.9, type: 'speed' as const },
  { s: 63, lane: 0.92, type: 'resize_shrink' as const },
  { s: 76.5, lane: 0.1, type: 'extra_life' as const },
  { s: 124.5, lane: 0.86, type: 'shield' as const },
  { s: 171, lane: 0.14, type: 'extra_life' as const },
];

const SPARK_LAYOUT = [
  { s: 12, lane: 0.18 },
  { s: 47, lane: 0.78 },
  { s: 86, lane: 0.4 },
  { s: 132, lane: 0.84 },
  { s: 167, lane: 0.24 },
] as const;

function obstaclesForSegment(giantId: GiantId, fromS: number, toS: number) {
  return GIANT_LEVEL_OBSTACLES[giantId].filter((o) => o.s >= fromS && o.s <= toS);
}

/**
 * Фиксированный уровень v1 для гиганта (укороченный маршрут, как `swami_template_v1`).
 * Один модификатор в начале маршрута (первые 15 m).
 */
export function buildGiantLevelV1(giantId: GiantId): LevelDefinition {
  const modifierKind = getModifierForGiant(giantId);
  return {
    id: `${giantId}${GIANT_LEVEL_ID_SUFFIX}`,
    version: 1,
    giantId,
    visualThemeId: GIANT_VISUAL_THEME[giantId],
    baseForwardSpeed: 4.5,
    ratingTargets: {
      targetTimeSec: 120,
      targetSparkCount: SPARK_LAYOUT.length,
    },
    segments: [
      {
        fromS: 0,
        toS: 60,
        modifier: { kind: modifierKind, durationSec: MODIFIER_DURATION_SEC },
        obstacles: obstaclesForSegment(giantId, 0, 60),
        boosters: BOOSTER_LAYOUT.filter((b) => b.s <= 60),
        sparks: SPARK_LAYOUT.filter((s) => s.s <= 60),
      },
      {
        fromS: 60,
        toS: 120,
        modifier: null,
        obstacles: obstaclesForSegment(giantId, 60, 120),
        boosters: BOOSTER_LAYOUT.filter((b) => b.s > 60 && b.s <= 120),
        sparks: SPARK_LAYOUT.filter((s) => s.s > 60 && s.s <= 120),
      },
      {
        fromS: 120,
        toS: 180,
        modifier: null,
        obstacles: obstaclesForSegment(giantId, 120, 180),
        boosters: BOOSTER_LAYOUT.filter((b) => b.s > 120),
        sparks: SPARK_LAYOUT.filter((s) => s.s > 120),
      },
    ],
  };
}
