import { GIANT_IDS, type GiantId } from '../ids/ids';
import { GIANT_UNLOCK_AVG_RATING } from './constants';
import { getUnlockedLevelCount } from './progression';

export function getGiantUnlockIndex(giantId: GiantId): number {
  return GIANT_IDS.indexOf(giantId);
}

/** Гигант доступен на карте по среднему рейтингу доставок. */
export function isGiantUnlockedOnMap(averageRating: number, giantId: GiantId): boolean {
  const index = getGiantUnlockIndex(giantId);
  if (index < 0) {
    return false;
  }
  return index < getUnlockedLevelCount(averageRating);
}

/** Минимальный средний рейтинг, чтобы открыть точку гиганта на карте. */
export function ratingRequiredForGiant(giantId: GiantId): number {
  const index = getGiantUnlockIndex(giantId);
  if (index <= 0) {
    return 0;
  }
  return GIANT_UNLOCK_AVG_RATING[index] ?? 5;
}
