import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useReducer,
  useRef,
  useState,
} from 'react';
import { Fragment, type CSSProperties, type PointerEvent } from 'react';
import { Navigate, useLocation, useNavigate } from 'react-router-dom';
import { getLevelForMission } from '../../content';
import {
  createGameSessionForMission,
  deriveGameplayPhase,
  FlightWorldSimulation,
  createWorldProjection,
  clampLaneCenterNorm,
  entityScreenTopPx,
  isWorldSVisible,
  listLevelBoosterSpawnsSorted,
  listLevelSparkSpawnsSorted,
  normYToScreenY,
  proximityVisibilityOpacity,
  screenYToNormY,
  worldSToScreenX,
} from '../../application';
import { squareObstacleHitboxPx } from '../../application/game/obstacleHitbox';
import {
  BOOSTER_PICKUP_HEIGHT_NORM,
  BOOSTER_PICKUP_WIDTH_M,
  COURIER_HITBOX_HEIGHT_NORM,
  COURIER_HITBOX_WIDTH_M,
  FLIGHT_BOOSTER_SCALE,
  FLIGHT_ENTITY_SCALE,
  FLIGHT_OBSTACLE_SCALE,
  FLIGHT_OBSTACLE_HITBOX_SCALE,
  FLIGHT_OBSTACLE_SHOW_HITBOX,
} from '../../domain';
import type { DeliveryOutcome, DeliveryRatingBreakdown, MissionRef } from '../../domain';
import {
  isGiantId,
  isTerminal,
  validateMissionRef,
} from '../../domain';
import { t } from '../../i18n';
import { useAppStore } from '../store/appStore';
import { RockRepairGadgetPanel } from '../minigames/RockRepairGadgetPanel';
import speedIcon from '../../infrastructure/assets/Images/speedIcon.png';
import coinIcon from '../../infrastructure/assets/Images/coinIcon.png';
import testObstacle from '../../infrastructure/assets/Images/testObstacle.png';
import { COURIER_PORTRAIT_BY_ID } from '../game/courierPortraits';
import { LevelProgressBar } from '../game/LevelProgressBar';
import { LevelLivesHud } from '../game/LevelLivesHud';
import { DeliveryResultModal } from '../game/DeliveryResultModal';
import { LevelFinishGiant } from '../game/GiantDeliveryUi';
import {
  FactorMirageObstacles,
  ModifierOverlays,
  playfieldShakeTransform,
} from '../game/ModifierOverlays';
import actionButtonBackground from '../../infrastructure/assets/Images/actionButtonBackground.png';

const KEYBOARD_TARGET_SPEED_NORM_PER_SEC = 1.35;
const COURIER_SPRITE_SCALE = FLIGHT_ENTITY_SCALE;
const ROUTE_FINISH_EPS_S = 0.001;

const finishButtonStyle: CSSProperties = {
  marginTop: 4,
  minWidth: 168,
  minHeight: 48,
  padding: '10px 20px',
  border: 'none',
  cursor: 'pointer',
  background: `url(${actionButtonBackground}) center / 100% 100% no-repeat`,
  color: '#fff',
  fontSize: 15,
  fontWeight: 800,
  letterSpacing: '0.04em',
  textTransform: 'uppercase',
};

const finishOverlayStyle: CSSProperties = {
  position: 'fixed',
  left: '50%',
  bottom: 'max(28px, env(safe-area-inset-bottom, 0px))',
  transform: 'translateX(-50%)',
  zIndex: 25,
  pointerEvents: 'auto',
};

function isGameplayFlightUiTarget(target: EventTarget | null): boolean {
  return target instanceof Element && target.closest('[data-gameplay-flight-ui]') != null;
}

function missionFromLocationState(state: unknown): MissionRef | null {
  if (state == null || typeof state !== 'object') {
    return null;
  }
  const raw = (state as { mission?: unknown }).mission;
  if (raw == null || typeof raw !== 'object') {
    return null;
  }
  const rec = raw as { giantId?: unknown; orderIndex?: unknown };
  if (typeof rec.giantId !== 'string' || typeof rec.orderIndex !== 'number') {
    return null;
  }
  if (!isGiantId(rec.giantId) || !Number.isInteger(rec.orderIndex)) {
    return null;
  }
  const mission: MissionRef = { giantId: rec.giantId, orderIndex: rec.orderIndex };
  return validateMissionRef(mission).ok ? mission : null;
}

export function GameplayScreen() {
  const courierId = useAppStore((s) => s.selectedCourierId);
  const settleDelivery = useAppStore((s) => s.settleDelivery);
  const ensureAndBeginDelivery = useAppStore((s) => s.ensureAndBeginDelivery);
  const location = useLocation();
  const navigate = useNavigate();
  const mission = useMemo(() => missionFromLocationState(location.state), [location.state]);

  const [, rerender] = useReducer((x: number) => x + 1, 0);
  const simRef = useRef<FlightWorldSimulation | null>(null);
  const rafRef = useRef(0);
  const lastTsRef = useRef(0);
  const loggedInitialYRef = useRef(false);
  const screenRootRef = useRef<HTMLDivElement | null>(null);
  const playfieldRef = useRef<HTMLDivElement | null>(null);
  const keyMoveRef = useRef({ up: false, down: false });
  const [fieldSize, setFieldSize] = useState({ w: 0, h: 0 });
  const [flightSurfaceReady, setFlightSurfaceReady] = useState(false);
  const [terminalOutcome, setTerminalOutcome] = useState<DeliveryOutcome | 'aborted' | null>(
    null,
  );
  const [resultStats, setResultStats] = useState<{
    rating: DeliveryRatingBreakdown;
    sparksCollected: number;
    sparksTotal: number;
  } | null>(null);
  const terminalOutcomeRef = useRef<DeliveryOutcome | 'aborted' | null>(null);
  const settledRef = useRef(false);

  const finalizeTerminalRun = useCallback(
    (outcome: DeliveryOutcome | 'aborted') => {
      const sim = simRef.current;
      if (sim == null || terminalOutcomeRef.current !== null) {
        return;
      }
      terminalOutcomeRef.current = outcome;
      const progressNow = sim.controller.getProgress();
      const stats = sim.session.buildDeliveryResultStats(progressNow.elapsedWorldTimeSec);
      setResultStats({
        rating: stats.rating,
        sparksCollected: stats.collectedSparks,
        sparksTotal: sim.getSnapshot().totalSparkCount,
      });
      if (!settledRef.current && mission != null) {
        settledRef.current = true;
        void settleDelivery({
          mission,
          outcome,
          rating: stats.rating,
          sparksCollected: stats.collectedSparks,
          sparksTotal: sim.getSnapshot().totalSparkCount,
        });
      }
      setTerminalOutcome(outcome);
      rerender();
    },
    [mission, settleDelivery],
  );

  const missionKey =
    mission == null ? 'none' : `${mission.giantId}:${mission.orderIndex}`;

  const flightLevel = useMemo(() => {
    const activeMission = mission ?? { giantId: 'swami' as const, orderIndex: 0 };
    return getLevelForMission(activeMission);
  }, [mission]);

  const boosterSpawns = useMemo(
    () => listLevelBoosterSpawnsSorted(flightLevel),
    [flightLevel],
  );
  const sparkSpawns = useMemo(() => listLevelSparkSpawnsSorted(flightLevel), [flightLevel]);

  useEffect(() => {
    if (courierId == null) {
      return;
    }
    const activeMission = mission ?? { giantId: 'swami' as const, orderIndex: 0 };
    const level = getLevelForMission(activeMission);
    const session = createGameSessionForMission(level, courierId, activeMission);
    terminalOutcomeRef.current = null;
    settledRef.current = false;
    setTerminalOutcome(null);
    setResultStats(null);
    simRef.current = new FlightWorldSimulation(session);
    const playfieldRect = playfieldRef.current?.getBoundingClientRect();
    const initialNormY =
      playfieldRect != null
        ? Math.min(
            1,
            Math.max(0, 1 - (window.innerHeight / 2 - playfieldRect.top) / playfieldRect.height),
          )
        : 0.5;
    simRef.current.courierY = initialNormY;
    simRef.current.setTargetY(initialNormY);
    loggedInitialYRef.current = false;
    lastTsRef.current = performance.now();
    setFlightSurfaceReady(true);
    rerender();

    const loop = (now: number) => {
      const sim = simRef.current;
      if (!sim) {
        return;
      }
      const prev = lastTsRef.current;
      lastTsRef.current = now;
      const dt = Math.min(0.25, Math.max(0, (now - prev) / 1000));
      const moveUp = keyMoveRef.current.up;
      const moveDown = keyMoveRef.current.down;
      const keyDir = (moveUp ? 1 : 0) - (moveDown ? 1 : 0);
      if (keyDir !== 0) {
        sim.setTargetY(sim.targetY + keyDir * KEYBOARD_TARGET_SPEED_NORM_PER_SEC * dt);
      }
      const phase = deriveGameplayPhase(sim.session);
      const progress = sim.controller.getProgress();
      const atRouteFinish = progress.distanceFromFinishS <= ROUTE_FINISH_EPS_S;
      if (phase === 'flying') {
        if (!atRouteFinish) {
          sim.tickFrame(dt);
          if (!loggedInitialYRef.current) {
            const rect = playfieldRef.current?.getBoundingClientRect();
            if (rect != null) {
              const proj = createWorldProjection(rect.width, rect.height);
              const courierScreenY = normYToScreenY(proj, sim.courierY);
              const rootRect = screenRootRef.current?.getBoundingClientRect();
              console.log('[GameplayScreen] initial courier Y', {
                courierNormY: sim.courierY,
                courierScreenYpx: courierScreenY,
                playfieldWidthPx: rect.width,
                playfieldHeightPx: rect.height,
                playfieldTopPx: rect.top,
                playfieldLeftPx: rect.left,
                screenRootWidthPx: rootRect?.width ?? null,
                screenRootHeightPx: rootRect?.height ?? null,
                screenRootTopPx: rootRect?.top ?? null,
                screenRootLeftPx: rootRect?.left ?? null,
                expectedCenterYpx: rect.height / 2,
                deltaFromCenterPx: courierScreenY - rect.height / 2,
              });
              loggedInitialYRef.current = true;
            }
          }
        }
        rerender();
      }
      const run = sim.session.getDeliveryRun();
      if (isTerminal(run)) {
        const outcome = run.kind === 'terminal' ? run.outcome : 'aborted';
        finalizeTerminalRun(outcome);
        return;
      }
      if (phase !== 'finished') {
        rafRef.current = requestAnimationFrame(loop);
      }
    };
    rafRef.current = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(rafRef.current);
      simRef.current?.session.abort();
      simRef.current = null;
      setFlightSurfaceReady(false);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps -- сессия полёта только при смене миссии/курьера
  }, [courierId, missionKey, mission, navigate, settleDelivery, finalizeTerminalRun]);

  useLayoutEffect(() => {
    if (!flightSurfaceReady) {
      return;
    }
    const el = playfieldRef.current;
    if (el == null) {
      return;
    }
    const applySize = (w: number, h: number) => {
      if (w > 0 && h > 0) {
        setFieldSize({ w, h });
      }
    };
    const syncFromRect = () => {
      const r = el.getBoundingClientRect();
      applySize(r.width, r.height);
    };
    syncFromRect();
    if (typeof ResizeObserver === 'undefined') {
      window.addEventListener('resize', syncFromRect);
      return () => window.removeEventListener('resize', syncFromRect);
    }
    const ro = new ResizeObserver((entries) => {
      const cr = entries[0]?.contentRect;
      if (cr != null) {
        applySize(cr.width, cr.height);
      }
    });
    ro.observe(el);
    window.addEventListener('resize', syncFromRect);
    return () => {
      ro.disconnect();
      window.removeEventListener('resize', syncFromRect);
    };
  }, [flightSurfaceReady]);

  useEffect(() => {
    const isUpKey = (e: KeyboardEvent): boolean =>
      e.code === 'KeyW' || e.code === 'ArrowUp' || e.key.toLowerCase() === 'ц';
    const isDownKey = (e: KeyboardEvent): boolean =>
      e.code === 'KeyS' || e.code === 'ArrowDown' || e.key.toLowerCase() === 'ы';
    const onKeyDown = (e: KeyboardEvent) => {
      if (isUpKey(e)) {
        keyMoveRef.current.up = true;
        e.preventDefault();
      } else if (isDownKey(e)) {
        keyMoveRef.current.down = true;
        e.preventDefault();
      }
    };
    const onKeyUp = (e: KeyboardEvent) => {
      if (isUpKey(e)) {
        keyMoveRef.current.up = false;
      } else if (isDownKey(e)) {
        keyMoveRef.current.down = false;
      }
    };
    const onBlur = () => {
      keyMoveRef.current.up = false;
      keyMoveRef.current.down = false;
    };
    window.addEventListener('keydown', onKeyDown);
    window.addEventListener('keyup', onKeyUp);
    window.addEventListener('blur', onBlur);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
      window.removeEventListener('keyup', onKeyUp);
      window.removeEventListener('blur', onBlur);
    };
  }, []);

  const setTargetFromClientY = useCallback((clientY: number) => {
    const sim = simRef.current;
    const el = playfieldRef.current;
    if (!sim || !el) {
      return;
    }
    const rect = el.getBoundingClientRect();
    const y = clientY - rect.top;
    const proj = createWorldProjection(rect.width, rect.height);
    const clickNormY = screenYToNormY(proj, y);
    const courierNormY = sim.courierY;
    const courierScreenY = normYToScreenY(proj, courierNormY);
    const courierHeightPx =
      COURIER_HITBOX_HEIGHT_NORM *
      rect.height *
      sim.session.getResizeShrinkHitboxMultiplier() *
      COURIER_SPRITE_SCALE;
    console.log('[GameplayScreen] click/courier Y', {
      clickYpx: y,
      clickNormY,
      courierYpx: courierScreenY,
      courierNormY,
      courierSpriteTopYpx: courierScreenY - courierHeightPx / 2,
      courierSpriteBottomYpx: courierScreenY + courierHeightPx / 2,
      courierSpriteHeightPx: courierHeightPx,
      targetNormYBefore: sim.targetY,
    });
    sim.setTargetY(clickNormY);
    sim.registerPointerActivity();
    rerender();
  }, []);

  const onPointerDown = useCallback((e: PointerEvent<HTMLDivElement>) => {
    if (isGameplayFlightUiTarget(e.target)) {
      return;
    }
    if (e.pointerType === 'mouse' && e.button !== 0) {
      return;
    }
    e.currentTarget.setPointerCapture(e.pointerId);
    setTargetFromClientY(e.clientY);
  }, [setTargetFromClientY]);

  const onPointerMove = useCallback((e: PointerEvent<HTMLDivElement>) => {
    if (isGameplayFlightUiTarget(e.target)) {
      return;
    }
    if (e.currentTarget.hasPointerCapture(e.pointerId) || e.buttons !== 0) {
      setTargetFromClientY(e.clientY);
    }
  }, [setTargetFromClientY]);

  const onPointerUp = useCallback((e: PointerEvent<HTMLDivElement>) => {
    const sim = simRef.current;
    const el = playfieldRef.current;
    if (!sim || !el) {
      return;
    }
    const rect = el.getBoundingClientRect();
    const y = e.clientY - rect.top;
    const proj = createWorldProjection(rect.width, rect.height);
    const rawNormY = 1 - y / rect.height;
    const clampedNormY = screenYToNormY(proj, y);
    const courierNormY = sim.courierY;
    const courierScreenY = normYToScreenY(proj, courierNormY);
    const courierHeightPx =
      COURIER_HITBOX_HEIGHT_NORM *
      rect.height *
      sim.session.getResizeShrinkHitboxMultiplier() *
      COURIER_SPRITE_SCALE;
    console.log('[GameplayScreen] pointerup Y', {
      pointerType: e.pointerType,
      releaseYpx: y,
      rawNormY,
      clampedNormY,
      courierYpx: courierScreenY,
      courierNormY,
      courierSpriteTopYpx: courierScreenY - courierHeightPx / 2,
      courierSpriteBottomYpx: courierScreenY + courierHeightPx / 2,
      courierSpriteHeightPx: courierHeightPx,
      targetNormYCurrent: sim.targetY,
    });
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
  }, []);

  const onConfirmFinish = useCallback(() => {
    const activeSim = simRef.current;
    if (activeSim == null) {
      return;
    }
    if (!isTerminal(activeSim.session.getDeliveryRun())) {
      activeSim.session.completeLevel();
    }
    const run = activeSim.session.getDeliveryRun();
    const outcome = run.kind === 'terminal' ? run.outcome : 'completed';
    finalizeTerminalRun(outcome);
  }, [finalizeTerminalRun]);

  if (courierId == null) {
    return <Navigate to="/courier" replace />;
  }

  const sim = simRef.current;
  if (sim == null) {
    return (
      <div style={{ padding: 24 }}>
        <p>{t('shell.splash.loading')}</p>
      </div>
    );
  }

  const session = sim.session;
  const snap = sim.getSnapshot();
  const playfieldRect = playfieldRef.current?.getBoundingClientRect();
  const projWidthPx =
    playfieldRect != null && playfieldRect.width > 0 ? playfieldRect.width : fieldSize.w;
  const projHeightPx =
    playfieldRect != null && playfieldRect.height > 0 ? playfieldRect.height : fieldSize.h;
  const proj = createWorldProjection(projWidthPx, projHeightPx);
  const phase = deriveGameplayPhase(session);
  const run = session.getDeliveryRun();
  const maxLives = session.maxLivesBeforeMinigame;
  const extraLifeCharges = session.getExtraLifeCharges();
  const strikesTowardMinigame = run.kind === 'flying' ? run.strikesTowardMinigame : 0;
  const courierScreenY = normYToScreenY(proj, snap.courierY);
  const courierScreenX = proj.courierScreenX;

  const flightProgress = sim.controller.getProgress();
  const routeProgress =
    flightProgress.routeEndS > 0
      ? flightProgress.distanceAlongRouteS / flightProgress.routeEndS
      : 0;
  const reachedRouteFinish =
    !isTerminal(run) && flightProgress.distanceFromFinishS <= ROUTE_FINISH_EPS_S;

  const modifier = snap.activeModifier;
  const flash = snap.flashCourier;
  const activeMission = mission ?? { giantId: 'swami' as const, orderIndex: 0 };
  const courierSpriteSrc = COURIER_PORTRAIT_BY_ID[courierId];
  const courierWidthPx = COURIER_HITBOX_WIDTH_M * proj.pxPerMeter;
  const courierHeightPx =
    COURIER_HITBOX_HEIGHT_NORM * proj.playfieldHeightPx * session.getResizeShrinkHitboxMultiplier();
  const courierSpriteWidthPx = courierWidthPx * COURIER_SPRITE_SCALE;
  const courierSpriteHeightPx = courierHeightPx * COURIER_SPRITE_SCALE;
  const worldTimeSec = flightProgress.elapsedWorldTimeSec;
  const playfieldTransform = playfieldShakeTransform(modifier, worldTimeSec);

  return (
    <div
      ref={screenRootRef}
      style={{
        position: 'relative',
        display: 'flex',
        flexDirection: 'column',
        height: '100dvh',
        maxHeight: '100dvh',
        background: '#1a1030',
        color: '#eee',
        overflow: 'hidden',
      }}
    >
      <div
        ref={playfieldRef}
        style={{
          flex: 1,
          position: 'relative',
          margin: 0,
          borderRadius: 8,
          overflow: 'hidden',
          touchAction: 'none',
          background: 'linear-gradient(180deg, #4a6fa5 0%, #7ab89a 55%, #c9a86c 100%)',
          transform: playfieldTransform,
        }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={(e) => {
          if (e.currentTarget.hasPointerCapture(e.pointerId)) {
            e.currentTarget.releasePointerCapture(e.pointerId);
          }
        }}
      >
        <LevelProgressBar
          elapsedSec={flightProgress.elapsedWorldTimeSec}
          distanceFromFinishM={flightProgress.distanceFromFinishS}
          routeProgress={routeProgress}
        />
        <LevelLivesHud
          maxLives={maxLives}
          strikes={strikesTowardMinigame}
          extraLifeCharges={extraLifeCharges}
          minigameRequired={run.kind === 'minigame_required'}
          hitFlash={flash}
          activeBoosters={session.getActiveBoosterKinds()}
        />

        <ModifierOverlays
          modifier={modifier}
          courierScreenX={courierScreenX}
          courierScreenY={courierScreenY}
          playfieldWidthPx={proj.playfieldWidthPx}
          playfieldHeightPx={proj.playfieldHeightPx}
          worldTimeSec={worldTimeSec}
          courierS={snap.courierS}
        />

        <FactorMirageObstacles
          modifier={modifier}
          courierScreenX={courierScreenX}
          courierScreenY={courierScreenY}
          playfieldWidthPx={proj.playfieldWidthPx}
          playfieldHeightPx={proj.playfieldHeightPx}
        />

        {boosterSpawns.map((b) => {
          if (sim.isBoosterCollected(b.segmentIndex, b.spawnIndex)) {
            return null;
          }
          const w = BOOSTER_PICKUP_WIDTH_M * proj.pxPerMeter * FLIGHT_BOOSTER_SCALE;
          const h = BOOSTER_PICKUP_HEIGHT_NORM * proj.playfieldHeightPx * FLIGHT_BOOSTER_SCALE;
          if (!isWorldSVisible(proj, b.s, snap.courierS, w)) {
            return null;
          }
          const x = worldSToScreenX(proj, b.s, snap.courierS);
          const laneY = clampLaneCenterNorm(
            b.lane,
            (BOOSTER_PICKUP_HEIGHT_NORM * FLIGHT_BOOSTER_SCALE) / 2,
          );
          const top = entityScreenTopPx(proj, laneY, h);
          const boosterOpacity = proximityVisibilityOpacity(b.s, snap.courierS, modifier);
          return (
            <img
              key={`${b.segmentIndex}:${b.spawnIndex}`}
              src={speedIcon}
              alt=""
              title={b.type}
              style={{
                position: 'absolute',
                left: x - w / 2,
                top,
                width: w,
                height: h,
                objectFit: 'contain',
                zIndex: 1,
                opacity: boosterOpacity,
                pointerEvents: 'none',
              }}
            />
          );
        })}

        {sparkSpawns.map((spark) => {
          if (sim.isSparkCollected(spark.segmentIndex, spark.spawnIndex)) {
            return null;
          }
          const w = BOOSTER_PICKUP_WIDTH_M * proj.pxPerMeter * FLIGHT_BOOSTER_SCALE * 0.85;
          const h = BOOSTER_PICKUP_HEIGHT_NORM * proj.playfieldHeightPx * FLIGHT_BOOSTER_SCALE * 0.85;
          if (!isWorldSVisible(proj, spark.s, snap.courierS, w)) {
            return null;
          }
          const x = worldSToScreenX(proj, spark.s, snap.courierS);
          const laneY = clampLaneCenterNorm(
            spark.lane,
            (BOOSTER_PICKUP_HEIGHT_NORM * FLIGHT_BOOSTER_SCALE) / 2,
          );
          const top = entityScreenTopPx(proj, laneY, h);
          const sparkOpacity = proximityVisibilityOpacity(spark.s, snap.courierS, modifier);
          return (
            <img
              key={`spark:${spark.segmentIndex}:${spark.spawnIndex}`}
              src={coinIcon}
              alt=""
              style={{
                position: 'absolute',
                left: x - w / 2,
                top,
                width: w,
                height: h,
                objectFit: 'contain',
                zIndex: 2,
                opacity: sparkOpacity,
                pointerEvents: 'none',
                filter: 'drop-shadow(0 0 4px rgba(255, 214, 95, 0.95))',
              }}
            />
          );
        })}

        {snap.obstacles.map((o) => {
          if (o.consumed) {
            return null;
          }
          const spriteW = o.widthM * proj.pxPerMeter * FLIGHT_OBSTACLE_SCALE;
          const spriteH = o.heightNorm * proj.playfieldHeightPx * FLIGHT_OBSTACLE_SCALE;
          const { widthPx: hitboxSide, heightPx: hitboxSideY } = squareObstacleHitboxPx(
            o.widthM,
            o.heightNorm,
            proj.pxPerMeter,
            proj.playfieldHeightPx,
            FLIGHT_OBSTACLE_HITBOX_SCALE,
          );
          if (!isWorldSVisible(proj, o.worldS, snap.courierS, hitboxSide)) {
            return null;
          }
          const x = worldSToScreenX(proj, o.worldS, snap.courierS);
          const top = entityScreenTopPx(proj, o.lane, hitboxSideY);
          const hitboxLeft = x - hitboxSide / 2;
          const spriteLeft = x - spriteW / 2;
          const spriteTop = entityScreenTopPx(proj, o.lane, spriteH);
          const obstacleOpacity = proximityVisibilityOpacity(o.worldS, snap.courierS, modifier);
          return (
            <Fragment key={o.id}>
              {FLIGHT_OBSTACLE_SHOW_HITBOX ? (
                <div
                  aria-hidden
                  style={{
                    position: 'absolute',
                    left: hitboxLeft,
                    top,
                    width: hitboxSide,
                    height: hitboxSideY,
                    boxSizing: 'border-box',
                    border: '2px solid rgba(255, 72, 72, 0.9)',
                    background: 'rgba(255, 72, 72, 0.12)',
                    zIndex: 2,
                    opacity: obstacleOpacity,
                    pointerEvents: 'none',
                  }}
                />
              ) : null}
              <img
                src={testObstacle}
                alt=""
                title={o.type}
                style={{
                  position: 'absolute',
                  left: spriteLeft,
                  top: spriteTop,
                  width: spriteW,
                  height: spriteH,
                  objectFit: 'contain',
                  zIndex: 3,
                  opacity: obstacleOpacity,
                  pointerEvents: 'none',
                }}
              />
            </Fragment>
          );
        })}

        <img
          src={courierSpriteSrc}
          alt={courierId}
          style={{
            position: 'absolute',
            left: courierScreenX - courierSpriteWidthPx / 2,
            top: entityScreenTopPx(proj, snap.courierY, courierSpriteHeightPx),
            width: courierSpriteWidthPx,
            height: courierSpriteHeightPx,
            objectFit: 'contain',
            zIndex: 5,
            opacity: flash ? 0.8 : 1,
            filter: flash ? 'brightness(1.35) saturate(0.9)' : undefined,
            transition: 'opacity 0.05s, filter 0.05s',
            pointerEvents: 'none',
          }}
        />

      </div>

      {reachedRouteFinish ? (
        <div data-gameplay-flight-ui style={finishOverlayStyle}>
          <LevelFinishGiant
            giantId={activeMission.giantId}
            speech={t('game.play.thankYou')}
            footer={
              <button
                type="button"
                style={finishButtonStyle}
                onPointerDown={(e) => e.stopPropagation()}
                onClick={(e) => {
                  e.stopPropagation();
                  onConfirmFinish();
                }}
              >
                {t('game.play.finishDelivery')}
              </button>
            }
          />
        </div>
      ) : null}

      {phase === 'minigame_required' ? (
        <RockRepairGadgetPanel
          onWin={() => {
            session.resolveMinigameWin();
            rerender();
          }}
          onLose={() => {
            session.resolveMinigameLoss();
            rerender();
          }}
        />
      ) : null}

      {terminalOutcome != null ? (
        <DeliveryResultModal
          mission={activeMission}
          outcome={terminalOutcome}
          rating={resultStats?.rating ?? null}
          sparksCollected={resultStats?.sparksCollected ?? snap.collectedSparkCount}
          sparksTotal={resultStats?.sparksTotal ?? snap.totalSparkCount}
          onRetry={
            terminalOutcome !== 'completed' || (resultStats?.rating.totalScore ?? 0) < 5
              ? () => {
                  void (async () => {
                    const begin = await ensureAndBeginDelivery(activeMission);
                    if (!begin.ok) {
                      return;
                    }
                    navigate('/play', { replace: true, state: { mission: activeMission } });
                  })();
                }
              : undefined
          }
          onToHub={() => navigate('/game/map')}
        />
      ) : null}
    </div>
  );
}
