import type { LevelRatingTargets } from '../level/level';

export type DeliveryRatingInput = {
  elapsedSec: number;
  collectedSparks: number;
  collisions: number;
  targets: LevelRatingTargets;
};

export type DeliveryRatingBreakdown = {
  timeScore: number;
  sparkScore: number;
  skillScore: number;
  totalScore: number;
  isPerfect: boolean;
};

const TIME_MAX = 2;
const SPARK_MAX = 2;
const SKILL_MAX = 1;
const TOTAL_MAX = 5;

function clamp01(v: number): number {
  return Math.min(1, Math.max(0, v));
}

function round1(v: number): number {
  return Math.round(v * 10) / 10;
}

export function calculateDeliveryRating(input: DeliveryRatingInput): DeliveryRatingBreakdown {
  const safeElapsed = Math.max(0.0001, input.elapsedSec);
  const safeSparks = Math.max(0, input.collectedSparks);
  const safeCollisions = Math.max(0, input.collisions);

  const timeRatio = clamp01(input.targets.targetTimeSec / safeElapsed);
  const sparkRatio = input.targets.targetSparkCount > 0
    ? clamp01(safeSparks / input.targets.targetSparkCount)
    : 1;
  const skillRatio = clamp01(1 - safeCollisions / 3);

  const timeScore = round1(timeRatio * TIME_MAX);
  const sparkScore = round1(sparkRatio * SPARK_MAX);
  const skillScore = round1(skillRatio * SKILL_MAX);
  const totalScore = round1(Math.min(TOTAL_MAX, timeScore + sparkScore + skillScore));

  return {
    timeScore,
    sparkScore,
    skillScore,
    totalScore,
    isPerfect: totalScore === TOTAL_MAX,
  };
}
