import type { LevelDefinition } from '../../domain';

export type LevelSparkSpawnEntry = {
  segmentIndex: number;
  spawnIndex: number;
  s: number;
  lane: number;
};

export function listLevelSparkSpawnsSorted(level: LevelDefinition): LevelSparkSpawnEntry[] {
  const out: LevelSparkSpawnEntry[] = [];
  for (let si = 0; si < level.segments.length; si += 1) {
    const seg = level.segments[si];
    if (!seg.sparks) {
      continue;
    }
    for (let spi = 0; spi < seg.sparks.length; spi += 1) {
      const spark = seg.sparks[spi];
      out.push({ segmentIndex: si, spawnIndex: spi, s: spark.s, lane: spark.lane });
    }
  }
  out.sort(
    (a, b) => a.s - b.s || a.segmentIndex - b.segmentIndex || a.spawnIndex - b.spawnIndex,
  );
  return out;
}
