import { BOOSTER_KINDS } from '../catalog/boosters';
import { MODIFIER_DURATION_SEC, MODIFIER_KINDS } from '../catalog/modifiers';
import { isObstacleAllowedForGiant } from '../catalog/giantsObstacles';
import type { LevelDefinition, LevelSegment, ObstacleSpawn } from './level';

export type LevelValidationResult = {
  ok: boolean;
  errors: string[];
};

function countModifiersInLevel(level: LevelDefinition): number {
  let n = 0;
  for (const seg of level.segments) {
    if (seg.modifier != null) n += 1;
  }
  return n;
}

/**
 * Геометрия маршрута: границы сегментов, все `s` в [fromS, toS], сортировка по `fromS`, без перекрытия соседей.
 */
export function validateLevelSpawns(level: LevelDefinition): LevelValidationResult {
  const errors = collectSpawnGeometryErrors(level);
  return { ok: errors.length === 0, errors };
}

function collectSpawnGeometryErrors(level: LevelDefinition): string[] {
  const errors: string[] = [];

  if (!Array.isArray(level.segments) || level.segments.length === 0) {
    errors.push('segments must be a non-empty array');
    return errors;
  }

  for (let i = 0; i < level.segments.length; i++) {
    const seg = level.segments[i];
    const prefix = `segments[${i}]`;

    if (!Number.isFinite(seg.fromS) || !Number.isFinite(seg.toS)) {
      errors.push(`${prefix}: fromS and toS must be finite numbers`);
      continue;
    }
    if (seg.fromS >= seg.toS) {
      errors.push(`${prefix}: fromS must be less than toS`);
      continue;
    }

    const { fromS, toS } = seg;

    if (seg.obstacles) {
      let oi = 0;
      for (const o of seg.obstacles) {
        const ctx = `${prefix}.obstacles[${oi}]`;
        if (!Number.isFinite(o.s)) {
          errors.push(`${ctx}: obstacle.s must be a finite number`);
        } else if (o.s < fromS || o.s > toS) {
          errors.push(
            `${ctx}: obstacle.s (${o.s}) must be within segment [${fromS}, ${toS}]`,
          );
        }
        oi += 1;
      }
    }

    if (seg.boosters) {
      let bi = 0;
      for (const b of seg.boosters) {
        const ctx = `${prefix}.boosters[${bi}]`;
        if (!Number.isFinite(b.s)) {
          errors.push(`${ctx}: booster.s must be a finite number`);
        } else if (b.s < fromS || b.s > toS) {
          errors.push(
            `${ctx}: booster.s (${b.s}) must be within segment [${fromS}, ${toS}]`,
          );
        }
        if (!Number.isFinite(b.lane)) {
          errors.push(`${ctx}: lane must be a finite number`);
        }
        bi += 1;
      }
    }

    if (seg.sparks) {
      let si = 0;
      for (const spark of seg.sparks) {
        const ctx = `${prefix}.sparks[${si}]`;
        if (!Number.isFinite(spark.s)) {
          errors.push(`${ctx}: spark.s must be a finite number`);
        } else if (spark.s < fromS || spark.s > toS) {
          errors.push(
            `${ctx}: spark.s (${spark.s}) must be within segment [${fromS}, ${toS}]`,
          );
        }
        if (!Number.isFinite(spark.lane)) {
          errors.push(`${ctx}: lane must be a finite number`);
        }
        si += 1;
      }
    }
  }

  for (let i = 0; i < level.segments.length - 1; i++) {
    const a = level.segments[i];
    const b = level.segments[i + 1];
    if (!Number.isFinite(a.fromS) || !Number.isFinite(a.toS)) continue;
    if (!Number.isFinite(b.fromS) || !Number.isFinite(b.toS)) continue;
    if (b.fromS < a.fromS) {
      errors.push(
        `segments[${i + 1}].fromS must be >= segments[${i}].fromS (sort order by fromS)`,
      );
    }
    if (b.fromS < a.toS) {
      errors.push(
        `segments[${i}] and [${i + 1}] overlap in s: [${a.fromS},${a.toS}) vs [${b.fromS},${b.toS})`,
      );
    }
  }

  return errors;
}

function validateObstacleSpawnSemantics(
  level: LevelDefinition,
  spawn: ObstacleSpawn,
  context: string,
): string[] {
  const errors: string[] = [];
  if (!isObstacleAllowedForGiant(level.giantId, spawn.type)) {
    errors.push(
      `${context}: obstacle type "${spawn.type}" is not allowed for giant "${level.giantId}"`,
    );
  }
  return errors;
}

function validateSegmentSemantics(level: LevelDefinition, seg: LevelSegment, index: number): string[] {
  const errors: string[] = [];
  const prefix = `segments[${index}]`;

  if (!Number.isFinite(seg.fromS) || !Number.isFinite(seg.toS)) {
    return errors;
  }
  if (seg.fromS >= seg.toS) {
    return errors;
  }

  if (seg.obstacles) {
    let oi = 0;
    for (const o of seg.obstacles) {
      errors.push(...validateObstacleSpawnSemantics(level, o, `${prefix}.obstacles[${oi}]`));
      oi += 1;
    }
  }

  if (seg.boosters) {
    let bi = 0;
    for (const b of seg.boosters) {
      if (!(BOOSTER_KINDS as readonly string[]).includes(b.type)) {
        errors.push(`${prefix}.boosters[${bi}]: unknown booster type "${b.type}"`);
      }
      bi += 1;
    }
  }

  if (seg.modifier != null && seg.modifier !== undefined) {
    const m = seg.modifier;
    if (!(MODIFIER_KINDS as readonly string[]).includes(m.kind)) {
      errors.push(`${prefix}.modifier: unknown modifier kind "${m.kind}"`);
    }
    if (m.durationSec !== MODIFIER_DURATION_SEC) {
      errors.push(
        `${prefix}.modifier: durationSec must be ${MODIFIER_DURATION_SEC} (GDD), got ${m.durationSec}`,
      );
    }
  }

  return errors;
}

/**
 * Проверка инвариантов уровня для загрузки JSON и CI.
 * Включает {@link validateLevelSpawns} (геометрия `s`) и семантику типов / модификатора.
 */
export function validateLevelDefinition(level: LevelDefinition): LevelValidationResult {
  const errors: string[] = [];

  if (level.version !== 1) {
    errors.push(`version must be 1, got ${level.version}`);
  }
  if (typeof level.id !== 'string' || level.id.length === 0) {
    errors.push('id must be a non-empty string');
  }
  if (typeof level.visualThemeId !== 'string' || level.visualThemeId.length === 0) {
    errors.push('visualThemeId must be a non-empty string');
  }
  if (!Number.isFinite(level.baseForwardSpeed) || level.baseForwardSpeed <= 0) {
    errors.push('baseForwardSpeed must be a positive finite number');
  }
  const targets = level.ratingTargets;
  if (!Number.isFinite(targets?.targetTimeSec) || (targets?.targetTimeSec ?? 0) <= 0) {
    errors.push('ratingTargets.targetTimeSec must be a positive finite number');
  }
  if (
    !Number.isFinite(targets?.targetSparkCount) ||
    !Number.isInteger(targets?.targetSparkCount) ||
    (targets?.targetSparkCount ?? -1) < 0
  ) {
    errors.push('ratingTargets.targetSparkCount must be a non-negative integer');
  }

  errors.push(...collectSpawnGeometryErrors(level));

  if (!Array.isArray(level.segments) || level.segments.length === 0) {
    return { ok: errors.length === 0, errors };
  }

  const modCount = countModifiersInLevel(level);
  if (level.allowMultipleModifiers !== true && modCount > 1) {
    errors.push(
      `at most one segment with modifier per level (GDD), found ${modCount} segments with modifier`,
    );
  }

  let i = 0;
  let sparkCount = 0;
  for (const seg of level.segments) {
    errors.push(...validateSegmentSemantics(level, seg, i));
    sparkCount += seg.sparks?.length ?? 0;
    i += 1;
  }
  if (Number.isInteger(targets?.targetSparkCount) && targets.targetSparkCount !== sparkCount) {
    errors.push(
      `ratingTargets.targetSparkCount (${targets.targetSparkCount}) must match sparks in segments (${sparkCount})`,
    );
  }

  return { ok: errors.length === 0, errors };
}
