import type { ReactNode } from 'react';
import type { ModifierKind } from '../../domain';

type ModifierOverlaysProps = {
  modifier: ModifierKind | null;
  courierScreenX: number;
  courierScreenY: number;
  playfieldWidthPx: number;
  playfieldHeightPx: number;
  worldTimeSec: number;
  courierS: number;
};

function solarRayLeftPx(worldTimeSec: number, widthPx: number): number {
  const phase = (worldTimeSec % 6) / 6;
  return phase * (widthPx + 80) - 40;
}

export function ModifierOverlays({
  modifier,
  courierScreenX,
  courierScreenY,
  playfieldWidthPx,
  playfieldHeightPx,
  worldTimeSec,
}: ModifierOverlaysProps) {
  if (modifier == null) {
    return null;
  }

  const overlays: ReactNode[] = [];

  if (modifier === 'foam_fog') {
    overlays.push(
      <div
        key="foam_fog"
        style={{
          position: 'absolute',
          left: 0,
          top: 0,
          bottom: 0,
          width: '50%',
          background: 'rgba(40,40,60,0.72)',
          pointerEvents: 'none',
          zIndex: 4,
        }}
      />,
    );
  }

  if (modifier === 'dark_shu') {
    overlays.push(
      <div
        key="dark_shu"
        style={{
          position: 'absolute',
          inset: 0,
          background: 'rgba(0,0,0,0.7)',
          pointerEvents: 'none',
          zIndex: 3,
          maskImage: `radial-gradient(circle at ${courierScreenX}px ${courierScreenY}px, transparent 0, transparent ${playfieldHeightPx * 0.08 * 2}px, black ${playfieldHeightPx * 0.14}px)`,
          WebkitMaskImage: `radial-gradient(circle at ${courierScreenX}px ${courierScreenY}px, transparent 0, transparent ${playfieldHeightPx * 0.08 * 2}px, black ${playfieldHeightPx * 0.14}px)`,
        }}
      />,
    );
  }

  if (modifier === 'willy_blur') {
    overlays.push(
      <div
        key="willy_blur"
        style={{
          position: 'absolute',
          inset: 0,
          backdropFilter: 'blur(5px)',
          WebkitBackdropFilter: 'blur(5px)',
          pointerEvents: 'none',
          zIndex: 3,
        }}
      />,
      <div
        key="willy_glasses"
        aria-hidden
        style={{
          position: 'absolute',
          left: courierScreenX - playfieldWidthPx * 0.22,
          top: courierScreenY - playfieldHeightPx * 0.12,
          width: playfieldWidthPx * 0.44,
          height: playfieldHeightPx * 0.22,
          border: '3px solid rgba(80,60,40,0.55)',
          borderRadius: '40% 40% 45% 45%',
          pointerEvents: 'none',
          zIndex: 6,
        }}
      />,
    );
  }

  if (modifier === 'starfall') {
    overlays.push(
      <div
        key="starfall"
        style={{
          position: 'absolute',
          inset: 0,
          backgroundImage:
            'radial-gradient(2px 2px at 20% 30%, #fff, transparent), radial-gradient(2px 2px at 60% 70%, #ffe9a8, transparent), radial-gradient(1px 1px at 80% 20%, #fff, transparent)',
          backgroundSize: '100% 100%',
          opacity: 0.85,
          pointerEvents: 'none',
          zIndex: 3,
        }}
      />,
    );
  }

  if (modifier === 'yeti_icicle_corridor') {
    overlays.push(
      <div
        key="yeti_top"
        style={{
          position: 'absolute',
          left: 0,
          right: 0,
          top: 0,
          height: '14%',
          background: 'linear-gradient(180deg, rgba(180,220,255,0.9), rgba(180,220,255,0.35))',
          pointerEvents: 'none',
          zIndex: 4,
        }}
      />,
      <div
        key="yeti_bottom"
        style={{
          position: 'absolute',
          left: 0,
          right: 0,
          bottom: 0,
          height: '14%',
          background: 'linear-gradient(0deg, rgba(180,220,255,0.9), rgba(180,220,255,0.35))',
          pointerEvents: 'none',
          zIndex: 4,
        }}
      />,
    );
  }

  if (modifier === 'wave_surge') {
    overlays.push(
      <div
        key="wave_surge"
        style={{
          position: 'absolute',
          left: `${((worldTimeSec % 3) / 3) * 100}%`,
          top: 0,
          bottom: 0,
          width: '28%',
          background: 'linear-gradient(90deg, transparent, rgba(80,160,220,0.45), transparent)',
          pointerEvents: 'none',
          zIndex: 3,
        }}
      />,
    );
  }

  if (modifier === 'factor_smoke') {
    overlays.push(
      <div
        key="factor_smoke"
        style={{
          position: 'absolute',
          inset: 0,
          background: 'rgba(90,90,90,0.35)',
          pointerEvents: 'none',
          zIndex: 3,
        }}
      />,
    );
  }

  if (modifier === 'solar_ray') {
    overlays.push(
      <div
        key="solar_ray"
        style={{
          position: 'absolute',
          top: 0,
          bottom: 0,
          left: solarRayLeftPx(worldTimeSec, playfieldWidthPx),
          width: 56,
          background:
            'linear-gradient(90deg, transparent, rgba(255,220,80,0.55), rgba(255,160,40,0.35), transparent)',
          pointerEvents: 'none',
          zIndex: 4,
        }}
      />,
    );
  }

  if (modifier === 'swami_leaf_overlay') {
    overlays.push(
      <div
        key="swami_leaf"
        style={{
          position: 'absolute',
          right: '-4%',
          top: '18%',
          width: '52%',
          height: '64%',
          background: 'rgba(40,120,50,0.72)',
          borderRadius: '0 60% 40% 0',
          pointerEvents: 'none',
          zIndex: 5,
        }}
      />,
    );
  }

  if (modifier === 'inverted_controls') {
    overlays.push(
      <div
        key="inverted_hint"
        style={{
          position: 'absolute',
          left: 8,
          top: 8,
          padding: '4px 8px',
          fontSize: 11,
          background: 'rgba(0,0,0,0.55)',
          color: '#f8d0ff',
          borderRadius: 6,
          pointerEvents: 'none',
          zIndex: 8,
        }}
      >
        Инверсия управления
      </div>,
    );
  }

  if (modifier === 'serge_hypnosis') {
    overlays.push(
      <div
        key="serge_hypnosis"
        style={{
          position: 'absolute',
          inset: 0,
          boxShadow: 'inset 0 0 80px rgba(120,180,255,0.35)',
          pointerEvents: 'none',
          zIndex: 3,
        }}
      />,
    );
  }

  return <>{overlays}</>;
}

/** Ложные препятствия (миражи Фактора) — только визуал. */
export function playfieldShakeTransform(
  modifier: ModifierKind | null,
  worldTimeSec: number,
): string | undefined {
  if (modifier !== 'screen_shake') {
    return undefined;
  }
  const shakeX = Math.sin(worldTimeSec * 24) * 4;
  const shakeY = Math.cos(worldTimeSec * 19) * 3;
  return `translate(${shakeX}px, ${shakeY}px)`;
}

export function FactorMirageObstacles({
  modifier,
  courierScreenX,
  courierScreenY,
  playfieldWidthPx,
}: Pick<
  ModifierOverlaysProps,
  'modifier' | 'courierScreenX' | 'courierScreenY' | 'playfieldWidthPx' | 'playfieldHeightPx'
>) {
  if (modifier !== 'factor_mirage') {
    return null;
  }
  const spots = [
    { left: courierScreenX + playfieldWidthPx * 0.18, top: courierScreenY - 40 },
    { left: courierScreenX + playfieldWidthPx * 0.32, top: courierScreenY + 24 },
    { left: courierScreenX + playfieldWidthPx * 0.08, top: courierScreenY + 56 },
  ];
  return (
    <>
      {spots.map((spot, i) => (
        <div
          key={`mirage-${i}`}
          aria-hidden
          style={{
            position: 'absolute',
            left: spot.left - 28,
            top: spot.top - 20,
            width: 56,
            height: 40,
            background: 'rgba(200,160,80,0.35)',
            border: '2px dashed rgba(255,220,120,0.6)',
            borderRadius: 6,
            pointerEvents: 'none',
            zIndex: 2,
          }}
        />
      ))}
    </>
  );
}
