import { useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import type { DeliveryOutcome, DeliveryRatingBreakdown, MissionRef } from '../../domain';
import { isGiantId, validateMissionRef } from '../../domain';
import { DeliveryResultModal } from '../game/DeliveryResultModal';

type ResultState = {
  mission?: MissionRef;
  outcome?: DeliveryOutcome | 'aborted';
  rating?: DeliveryRatingBreakdown | null;
  sparksCollected?: number;
  sparksTotal?: number;
};

function parseState(state: unknown): ResultState {
  if (state == null || typeof state !== 'object') {
    return {};
  }
  const s = state as ResultState;
  if (s.mission != null) {
    const m = s.mission;
    if (!isGiantId(m.giantId) || !validateMissionRef(m).ok) {
      return { outcome: s.outcome };
    }
  }
  return s;
}

const gameBackdrop = {
  position: 'relative' as const,
  height: '100dvh',
  maxHeight: '100dvh',
  background: 'linear-gradient(180deg, #4a6fa5 0%, #7ab89a 55%, #c9a86c 100%)',
  overflow: 'hidden',
};

/** Fallback, если открыли `#/result` напрямую: та же модалка, что поверх полёта. */
export function ResultScreen() {
  const location = useLocation();
  const navigate = useNavigate();
  const { mission, outcome, rating, sparksCollected, sparksTotal } = parseState(location.state);

  useEffect(() => {
    if (outcome == null) {
      navigate('/game/map', { replace: true });
    }
  }, [outcome, navigate]);

  if (outcome == null) {
    return null;
  }

  return (
    <div style={gameBackdrop}>
      <DeliveryResultModal
        mission={mission ?? null}
        outcome={outcome}
        rating={rating ?? null}
        sparksCollected={sparksCollected ?? 0}
        sparksTotal={sparksTotal ?? 0}
        onRetry={
          outcome === 'completed'
            ? undefined
            : () => {
                if (mission != null) {
                  navigate('/play', { state: { mission } });
                } else {
                  navigate('/play');
                }
              }
        }
        onToHub={() => navigate('/game/map')}
      />
    </div>
  );
}
