import { GIANT_UNLOCK_AVG_RATING, UNLOCKED_LEVELS_MAX } from './constants';
import { roundRating } from './averageRating';

/** Уровень курьера по среднему рейтингу (0 при старте, +1 за каждый открытый гигант после первого). */
export function getCourierLevel(averageRating: number): number {
  return Math.max(0, getUnlockedLevelCount(averageRating) - 1);
}

/** Сколько из 12 уровней (гигантов) доступно по среднему рейтингу. */
export function getUnlockedLevelCount(averageRating: number): number {
  const safe = Math.max(0, averageRating);
  let unlocked = 1;
  for (let i = 1; i < UNLOCKED_LEVELS_MAX; i += 1) {
    const threshold = GIANT_UNLOCK_AVG_RATING[i] ?? 5;
    if (safe >= threshold) {
      unlocked = i + 1;
    } else {
      break;
    }
  }
  return unlocked;
}

/** Прогресс среднего рейтинга до открытия следующего гиганта (0 если уже на капе). */
export function getRatingProgressToNextLevel(averageRating: number): {
  currentLevel: number;
  ratingIntoLevel: number;
  ratingToNext: number;
} {
  const currentLevel = getCourierLevel(averageRating);
  const unlocked = getUnlockedLevelCount(averageRating);
  if (unlocked >= UNLOCKED_LEVELS_MAX) {
    return { currentLevel, ratingIntoLevel: 0, ratingToNext: 0 };
  }
  const currentThreshold = GIANT_UNLOCK_AVG_RATING[unlocked - 1] ?? 0;
  const nextThreshold = GIANT_UNLOCK_AVG_RATING[unlocked] ?? 5;
  return {
    currentLevel,
    ratingIntoLevel: roundRating(Math.max(0, averageRating - currentThreshold)),
    ratingToNext: roundRating(Math.max(0, nextThreshold - averageRating)),
  };
}
