import type { LevelDefinition, ObstacleKind, ObstacleSpawn } from '../../domain';
import {
  FLIGHT_OBSTACLE_HITBOX_SCALE,
  OBSTACLE_APPROACH_SPEED_MUL,
  getObstacleBehavior,
} from '../../domain';
import { squareObstacleHitboxRef } from './obstacleHitbox';
import { clampLaneCenterNorm } from './worldProjection';

export type ObstacleInstance = {
  id: string;
  type: ObstacleKind;
  /** Начальная дистанция по маршруту, м. */
  anchorS: number;
  /** Текущая дистанция по маршруту, м. */
  worldS: number;
  lane: number;
  motion: 'static' | 'toward_player';
  approachSpeedMps: number;
  widthM: number;
  heightNorm: number;
  /** Уже засчитан удар (объект «пройден» по strike). */
  consumed: boolean;
};

function parseCount(pattern: ObstacleSpawn['pattern']): number {
  const raw = pattern?.count;
  if (typeof raw === 'number' && Number.isFinite(raw) && raw >= 1) {
    return Math.floor(raw);
  }
  return 1;
}

function parseSpread(pattern: ObstacleSpawn['pattern'], key: 'spreadY' | 'spreadS'): number {
  const raw = pattern?.[key];
  if (typeof raw === 'number' && Number.isFinite(raw) && raw >= 0) {
    return raw;
  }
  return 0;
}

function expandOneSpawn(spawn: ObstacleSpawn, segmentIndex: number, spawnIndex: number): ObstacleInstance[] {
  const behavior = getObstacleBehavior(spawn.type);
  const count = parseCount(spawn.pattern);
  const spreadY = parseSpread(spawn.pattern, 'spreadY');
  const spreadS = parseSpread(spawn.pattern, 'spreadS');
  const mode = spawn.pattern?.mode ?? 'point';
  const baseLane = spawn.lane ?? 0.5;

  const out: ObstacleInstance[] = [];
  for (let i = 0; i < count; i += 1) {
    let lane = baseLane;
    let s = spawn.s;
    if (count > 1) {
      const t = count === 1 ? 0 : (i / (count - 1)) * 2 - 1;
      if (mode === 'line' || mode === 'arc' || mode === 'point') {
        lane = baseLane + t * spreadY;
        s = spawn.s + t * spreadS;
      }
    }
    const hitbox = squareObstacleHitboxRef(behavior.widthM, behavior.heightNorm);
    const halfHeightNorm = (hitbox.heightNorm * FLIGHT_OBSTACLE_HITBOX_SCALE) / 2;
    lane = clampLaneCenterNorm(lane, halfHeightNorm);
    const approachRaw = behavior.approachSpeedMps ?? 0;
    out.push({
      id: `${segmentIndex}:${spawnIndex}:${i}`,
      type: spawn.type,
      anchorS: s,
      worldS: s,
      lane,
      motion: behavior.motion,
      approachSpeedMps: approachRaw * OBSTACLE_APPROACH_SPEED_MUL,
      widthM: behavior.widthM,
      heightNorm: behavior.heightNorm,
      consumed: false,
    });
  }
  return out;
}

export function buildObstacleInstancesFromLevel(level: LevelDefinition): ObstacleInstance[] {
  const instances: ObstacleInstance[] = [];
  level.segments.forEach((seg, segmentIndex) => {
    seg.obstacles?.forEach((spawn, spawnIndex) => {
      instances.push(...expandOneSpawn(spawn, segmentIndex, spawnIndex));
    });
  });
  return instances.sort((a, b) => a.worldS - b.worldS || a.id.localeCompare(b.id));
}
