function assertGiantObstacleLayouts(): void {
  for (const giantId of GIANT_IDS) {
    for (const o of GIANT_LEVEL_OBSTACLES[giantId]) {
      if (o.s < 0 || o.s > 180) {
        throw new Error(`GIANT_LEVEL_OBSTACLES[${giantId}]: s=${o.s} out of [0, 180]`);
      }
      if (o.lane < 0 || o.lane > 1) {
        throw new Error(`GIANT_LEVEL_OBSTACLES[${giantId}]: lane=${o.lane} out of [0, 1]`);
      }
    }
  }
}

assertGiantObstacleLayouts();
