import type { ModifierKind } from '../../domain';

/** Нормализованный Y цели после тапа с учётом модификатора. */
export function mapTapTargetNormY(normY: number, modifier: ModifierKind | null): number {
  if (modifier === 'inverted_controls') {
    return 1 - normY;
  }
  return normY;
}

/** Ограничение коридора по Y во время модификатора. */
export function clampCourierNormY(normY: number, modifier: ModifierKind | null): number {
  let y = normY;
  if (modifier === 'yeti_icicle_corridor') {
    y = Math.min(0.85, Math.max(0.15, y));
  }
  return Math.min(1, Math.max(0, y));
}

/** Прозрачность объекта на маршруте (Луна Му). */
export function proximityVisibilityOpacity(
  objectS: number,
  courierS: number,
  modifier: ModifierKind | null,
): number {
  if (modifier !== 'proximity_visibility') {
    return 1;
  }
  const dist = Math.abs(objectS - courierS);
  if (dist <= 4) {
    return 1;
  }
  if (dist >= 14) {
    return 0.12;
  }
  return 0.12 + (0.88 * (14 - dist)) / 10;
}
