export type Aabb = {
  xMin: number;
  xMax: number;
  yMin: number;
  yMax: number;
};

export function aabbFromCenter(
  xCenter: number,
  yCenter: number,
  widthX: number,
  heightY: number,
): Aabb {
  const halfW = widthX / 2;
  const halfH = heightY / 2;
  return {
    xMin: xCenter - halfW,
    xMax: xCenter + halfW,
    yMin: yCenter - halfH,
    yMax: yCenter + halfH,
  };
}

export function aabbIntersects(a: Aabb, b: Aabb): boolean {
  return a.xMin < b.xMax && a.xMax > b.xMin && a.yMin < b.yMax && a.yMax > b.yMin;
}
