import { create } from 'zustand';
import {
  createStorageAdapterWithFallback,
  detectRuntime,
  loadPlayerEconomyFromBackend,
  loadPlayerEconomy,
  savePlayerEconomyToBackend,
  savePlayerEconomy,
  type StorageAdapter,
} from '../../infrastructure';
import type { CourierId } from '../../domain/ids/ids';
import type { ActionErrorCode } from '../components/GameStatusBanner';
import {
  beginDeliveryAttempt,
  createInitialPlayerEconomy,
  isCourierId,
  syncDeliveryPool,
  acknowledgeDailyPackComplete,
  findPoolEntryByGiant,
  isoDateFromMs,
  settleDeliveryAttempt,
  type BeginDeliveryResult,
  type MissionRef,
  type PlayerEconomyState,
  type SettleDeliveryInput,
  type SettleDeliveryResult,
  submitQuizAnswer as submitQuizAnswerDomain,
  claimDailyLoginReward as claimDailyLoginRewardDomain,
  buildDailyLoginStateWithStreak,
  type QuizAnswerResult,
  type DailyLoginClaimResult,
} from '../../domain';

export type HydrationStatus = 'loading' | 'ready' | 'error';

type AppStoreState = {
  hydrationStatus: HydrationStatus;
  hydrationError: string | null;
  onboardingComplete: boolean;
  selectedCourierId: CourierId | null;
  playerEconomy: PlayerEconomyState;
  /** Пропуски (дублирует economy для удобства HUD). */
  passesBalance: number;
  /** Предупреждение о проблемах синхронизации с backend (offline/fallback). */
  syncWarning: string | null;
  /** Последняя ошибка игрового действия (доставка / карта). */
  lastActionError: ActionErrorCode | null;
  lastActionErrorRatingRequired: number | null;
  /** Последнее изменение среднего рейтинга после доставки (для HUD на карте). */
  lastRatingDelta: number | null;
  bootstrap: () => Promise<void>;
  clearActionError: () => void;
  dismissSyncWarning: () => void;
  reportActionError: (code: ActionErrorCode, ratingRequired?: number) => void;
  setSelectedCourier: (id: CourierId) => Promise<void>;
  completeOnboarding: () => Promise<void>;
  refreshEconomy: () => Promise<void>;
  ensureAndBeginDelivery: (mission: MissionRef) => Promise<BeginDeliveryResult>;
  settleDelivery: (input: SettleDeliveryInput) => Promise<SettleDeliveryResult>;
  acknowledgeDailyPackCompleteModal: () => Promise<void>;
  submitQuizAnswer: (questionId: string, selectedIndex: number) => Promise<import('../../domain').QuizAnswerResult>;
  claimDailyLoginReward: () => Promise<DailyLoginClaimResult>;
  resetDailyLoginProgress: () => Promise<void>;
  seedDailyLoginStreakForDev: (streakDays: number) => Promise<void>;
};

let persistence: StorageAdapter | null = null;
let bootstrapInflight: Promise<void> | null = null;

function bootstrapErrorMessage(e: unknown): string {
  if (e instanceof Error) {
    return e.message;
  }
  if (typeof e === 'object' && e !== null) {
    const vk = e as {
      error_msg?: string;
      error_data?: { error_msg?: string };
    };
    if (typeof vk.error_msg === 'string' && vk.error_msg !== '') {
      return vk.error_msg;
    }
    const nested = vk.error_data?.error_msg;
    if (typeof nested === 'string' && nested !== '') {
      return nested;
    }
    try {
      return JSON.stringify(e);
    } catch {
      return String(e);
    }
  }
  return String(e);
}

function parseOnboardingComplete(raw: string | null): boolean {
  if (raw == null || raw === '') {
    return false;
  }
  return raw === '1' || raw === 'true';
}

const now = () => Date.now();

function sliceFromEconomy(economy: PlayerEconomyState) {
  return { playerEconomy: economy, passesBalance: economy.passesBalance };
}

async function persistEconomy(economy: PlayerEconomyState): Promise<void> {
  if (!persistence) {
    throw new Error('persistEconomy: persistence is not ready');
  }
  await savePlayerEconomy(persistence, economy);
  try {
    await savePlayerEconomyToBackend(economy);
    useAppStore.setState({ syncWarning: null });
  } catch (e) {
    console.warn('[shell] backend save failed, keeping local state only', e);
    useAppStore.setState({ syncWarning: syncWarningMessage('backend_save_failed') });
  }
}

function syncWarningMessage(code: string): string {
  if (code === 'backend_save_failed' || code === 'backend_load_failed') {
    return 'Синхронизация с сервером недоступна. Играем в локальном режиме.';
  }
  return code;
}

const initialEconomy = createInitialPlayerEconomy(0);

const initialSlice = {
  hydrationStatus: 'loading' as HydrationStatus,
  hydrationError: null as string | null,
  onboardingComplete: false,
  selectedCourierId: null as CourierId | null,
  playerEconomy: initialEconomy,
  passesBalance: 0,
  syncWarning: null as string | null,
  lastActionError: null as ActionErrorCode | null,
  lastActionErrorRatingRequired: null as number | null,
  lastRatingDelta: null as number | null,
};

export const useAppStore = create<AppStoreState>((set, get) => ({
  ...initialSlice,

  bootstrap: async () => {
    if (bootstrapInflight != null) {
      return bootstrapInflight;
    }
    bootstrapInflight = (async () => {
      set({
        ...initialSlice,
        hydrationStatus: 'loading',
        hydrationError: null,
        syncWarning: null,
        lastActionError: null,
        lastActionErrorRatingRequired: null,
        lastRatingDelta: null,
      });
      try {
        const runtime = detectRuntime();
        persistence = await createStorageAdapterWithFallback(runtime.kind);
        const [rawOnboarding, rawCourier, rawPasses] = await Promise.all([
          persistence.get('onboarding_complete'),
          persistence.get('selected_courier_id'),
          persistence.get('passes_balance'),
        ]);
        const onboardingComplete = parseOnboardingComplete(rawOnboarding);
        let selectedCourierId: CourierId | null = null;
        if (rawCourier != null && rawCourier !== '' && isCourierId(rawCourier)) {
          selectedCourierId = rawCourier;
        }
        const economy = await loadPlayerEconomy(persistence, rawPasses, now());
        let syncedEconomy = economy;
        let syncWarning: string | null = null;
        try {
          const backendEconomy = await loadPlayerEconomyFromBackend();
          if (backendEconomy != null) {
            syncedEconomy = backendEconomy;
            await savePlayerEconomy(persistence, backendEconomy);
          }
        } catch (e) {
          console.warn('[shell] backend load failed, using local state only', e);
          syncWarning = syncWarningMessage('backend_load_failed');
        }
        set({
          onboardingComplete,
          selectedCourierId,
          hydrationStatus: 'ready',
          hydrationError: null,
          syncWarning,
          lastActionError: null,
          lastActionErrorRatingRequired: null,
          lastRatingDelta: null,
          ...sliceFromEconomy(syncedEconomy),
        });
      } catch (e) {
        const message = bootstrapErrorMessage(e);
        console.error('[shell] bootstrap failed', e);
        persistence = null;
        set({
          ...initialSlice,
          hydrationStatus: 'error',
          hydrationError: message,
        });
      }
    })();
    try {
      await bootstrapInflight;
    } finally {
      bootstrapInflight = null;
    }
  },

  setSelectedCourier: async (id: CourierId) => {
    if (!persistence) {
      throw new Error('setSelectedCourier: persistence is not ready');
    }
    await persistence.set('selected_courier_id', id);
    set({ selectedCourierId: id });
  },

  completeOnboarding: async () => {
    if (!persistence) {
      throw new Error('completeOnboarding: persistence is not ready');
    }
    await persistence.set('onboarding_complete', '1');
    set({ onboardingComplete: true });
  },

  clearActionError: () => {
    set({ lastActionError: null, lastActionErrorRatingRequired: null });
  },

  dismissSyncWarning: () => {
    set({ syncWarning: null });
  },

  reportActionError: (code, ratingRequired) => {
    set({
      lastActionError: code,
      lastActionErrorRatingRequired:
        ratingRequired != null ? ratingRequired : null,
    });
  },

  refreshEconomy: async () => {
    const synced = syncDeliveryPool(get().playerEconomy, now());
    await persistEconomy(synced);
    set(sliceFromEconomy(synced));
  },

  acknowledgeDailyPackCompleteModal: async () => {
    const synced = acknowledgeDailyPackComplete(get().playerEconomy, isoDateFromMs(now()));
    await persistEconomy(synced);
    set(sliceFromEconomy(synced));
  },

  ensureAndBeginDelivery: async (mission: MissionRef) => {
    const t = now();
    let economy = syncDeliveryPool(get().playerEconomy, t);
    const poolEntry = findPoolEntryByGiant(economy, mission.giantId);
    if (poolEntry == null) {
      set({ lastActionError: 'not_in_pool', lastActionErrorRatingRequired: null });
      return { ok: false as const, reason: 'not_in_pool' as const, state: economy };
    }
    const poolMission: MissionRef = {
      giantId: poolEntry.giantId,
      orderIndex: poolEntry.orderIndex,
    };
    const result = beginDeliveryAttempt(economy, poolMission, t);
    if (result.ok) {
      await persistEconomy(result.state);
      set({
        ...sliceFromEconomy(result.state),
        lastActionError: null,
        lastActionErrorRatingRequired: null,
        lastRatingDelta: null,
      });
    } else {
      set({ lastActionError: result.reason, lastActionErrorRatingRequired: null });
    }
    return result;
  },

  settleDelivery: async (input: SettleDeliveryInput) => {
    const result = settleDeliveryAttempt(get().playerEconomy, input);
    await persistEconomy(result.state);
    const lastRatingDelta = input.outcome === 'completed' ? result.ratingDelta : get().lastRatingDelta;
    set({ ...sliceFromEconomy(result.state), lastRatingDelta });
    return result;
  },

  submitQuizAnswer: async (questionId: string, selectedIndex: number): Promise<QuizAnswerResult> => {
    const prev = get().playerEconomy;
    const result = submitQuizAnswerDomain(prev, questionId, selectedIndex);
    if (result.state !== prev) {
      await persistEconomy(result.state);
      set(sliceFromEconomy(result.state));
    }
    return result;
  },

  claimDailyLoginReward: async (): Promise<DailyLoginClaimResult> => {
    const result = claimDailyLoginRewardDomain(get().playerEconomy);
    if (!result.alreadyClaimed && result.rewardPasses > 0) {
      await persistEconomy(result.state);
      set(sliceFromEconomy(result.state));
    }
    return result;
  },

  resetDailyLoginProgress: async (): Promise<void> => {
    const prev = get().playerEconomy;
    const state: PlayerEconomyState = {
      ...prev,
      streakDays: 0,
      lastLoginDate: null,
      lastDailyRewardClaimedDate: null,
      dailyLoginStreakCompleted: false,
    };
    await persistEconomy(state);
    set(sliceFromEconomy(state));
  },

  seedDailyLoginStreakForDev: async (streakDays: number): Promise<void> => {
    const prev = get().playerEconomy;
    const state = buildDailyLoginStateWithStreak(prev, streakDays);
    await persistEconomy(state);
    set(sliceFromEconomy(state));
  },
}));

/** Сброс для тестов (не вызывать из прод-кода). */
export function __resetAppStoreForTests(): void {
  persistence = null;
  bootstrapInflight = null;
  useAppStore.setState(initialSlice);
}

/** Тестовый доступ к адаптеру персистентности. */
export function __getPersistenceForTests(): StorageAdapter | null {
  return persistence;
}
