import type { LevelDefinition, ModifierKind } from '../../domain';
import { MODIFIER_DISTANCE_M } from '../../domain';

/** Активный модификатор по пройденному `s` (test-level-spec §6.2). */
export function getActiveModifierAtS(
  level: LevelDefinition,
  distanceS: number,
): ModifierKind | null {
  for (const seg of level.segments) {
    if (seg.modifier == null) {
      continue;
    }
    const start = seg.fromS;
    const end = start + MODIFIER_DISTANCE_M;
    if (distanceS >= start && distanceS < end) {
      return seg.modifier.kind;
    }
  }
  return null;
}
