import { GIANT_IDS, type GiantId, type LevelDefinition, type MissionRef } from '../../domain';
import { buildGiantLevelV1 } from './buildGiantLevelV1';

/**
 * Один фиксированный уровень на гиганта (`{giantId}_v1`).
 */
export const LEVEL_BY_GIANT_ID: Record<GiantId, LevelDefinition> = Object.fromEntries(
  GIANT_IDS.map((giantId) => [giantId, buildGiantLevelV1(giantId)]),
) as Record<GiantId, LevelDefinition>;

export function getLevelForGiant(giantId: GiantId): LevelDefinition {
  return LEVEL_BY_GIANT_ID[giantId];
}

/** Уровень по миссии: заказ влияет только на тексты, геометрия — по гиганту. */
export function getLevelForMission(mission: MissionRef): LevelDefinition {
  return getLevelForGiant(mission.giantId);
}
