import { COURIER_SCREEN_X_RATIO, PLAYFIELD_WIDTH_M } from '../../domain';

export type WorldProjection = {
  pxPerMeter: number;
  playfieldWidthPx: number;
  playfieldHeightPx: number;
  courierScreenX: number;
};

export function createWorldProjection(
  playfieldWidthPx: number,
  playfieldHeightPx: number,
): WorldProjection {
  const pxPerMeter = playfieldWidthPx / PLAYFIELD_WIDTH_M;
  return {
    pxPerMeter,
    playfieldWidthPx,
    playfieldHeightPx,
    courierScreenX: playfieldWidthPx * COURIER_SCREEN_X_RATIO,
  };
}

/** Экранная X для точки маршрута `worldS` при курьере на `courierS`. */
export function worldSToScreenX(
  proj: WorldProjection,
  worldS: number,
  courierS: number,
): number {
  return proj.courierScreenX + (worldS - courierS) * proj.pxPerMeter;
}

export function normYToScreenY(proj: WorldProjection, normY: number): number {
  const y = 1 - Math.min(1, Math.max(0, normY));
  return y * proj.playfieldHeightPx;
}

export function screenYToNormY(proj: WorldProjection, screenY: number): number {
  const y = screenY / proj.playfieldHeightPx;
  return 1 - Math.min(1, Math.max(0, y));
}

/** Центр по lane (norm Y), чтобы половина высоты объекта оставалась в [0, 1]. */
export function clampLaneCenterNorm(lane: number, entityHalfHeightNorm: number): number {
  const half = Math.max(0, Math.min(0.5, entityHalfHeightNorm));
  return Math.min(1 - half, Math.max(half, lane));
}

/** `top` для absolute-позиционирования: центр по lane, без выхода за playfield по Y. */
export function entityScreenTopPx(
  proj: WorldProjection,
  normY: number,
  heightPx: number,
): number {
  const centerY = normYToScreenY(proj, normY);
  if (heightPx >= proj.playfieldHeightPx) {
    return 0;
  }
  return Math.min(
    proj.playfieldHeightPx - heightPx,
    Math.max(0, centerY - heightPx / 2),
  );
}

/**
 * Сущность видна, пока её горизонтальный AABB пересекает playfield:
 * появляется, когда входит справа за экран, исчезает после выхода влево.
 */
export function isEntityHorizontallyVisible(
  proj: WorldProjection,
  centerScreenX: number,
  entityWidthPx: number,
): boolean {
  const halfW = Math.max(0, entityWidthPx) / 2;
  return (
    centerScreenX + halfW > 0 && centerScreenX - halfW < proj.playfieldWidthPx
  );
}

export function isWorldSVisible(
  proj: WorldProjection,
  worldS: number,
  courierS: number,
  entityWidthPx: number,
): boolean {
  const x = worldSToScreenX(proj, worldS, courierS);
  return isEntityHorizontallyVisible(proj, x, entityWidthPx);
}
