import { GIANT_IDS, type GiantId } from '../../domain';

/**
 * Точка доставки на полной карте: доли от ширины/высоты изображения (0–1).
 * Координаты — черновые, подправьте под художественную раскладку `mapWindowBackground.png` (1920×1080).
 */
export type MapDeliveryPoint = {
  giantId: GiantId;
  /** Подпись на маркере (короткое имя локации). */
  label: string;
  /** 0 = обычный, 1 = срочный (красная подложка) */
  urgent: boolean;
  x: number;
  y: number;
};

/** Первый заказ гиганта — пока нет прогрессии по индексам на карте. */
export const MAP_DEFAULT_ORDER_INDEX = 0;

/**
 * Все неподвижные гиганты на карте мира Шу (порядок = обход слева направо, сверху вниз).
 * `x`/`y` разнесены, чтобы маркеры не перекрывались на типичном вьюпорте.
 */
export const MAP_DELIVERY_POINTS: readonly MapDeliveryPoint[] = [
  { giantId: 'luna_mu', label: 'Луна Му', urgent: false, x: 0.12, y: 0.3 },
  { giantId: 'haunted_house', label: 'Призраки', urgent: false, x: 0.2, y: 0.62 },
  { giantId: 'yeti', label: 'Йети', urgent: true, x: 0.32, y: 0.2 },
  { giantId: 'uncle_willy', label: 'Вилли', urgent: false, x: 0.34, y: 0.46 },
  { giantId: 'factor', label: 'Фактор', urgent: false, x: 0.4, y: 0.78 },
  { giantId: 'swami', label: 'Свами', urgent: false, x: 0.5, y: 0.54 },
  { giantId: 'rose_observatory', label: 'Роза', urgent: false, x: 0.54, y: 0.24 },
  { giantId: 'serge', label: 'Серж', urgent: false, x: 0.6, y: 0.14 },
  { giantId: 'sol', label: 'Сол', urgent: false, x: 0.58, y: 0.38 },
  { giantId: 'drakocha', label: 'Дракоча', urgent: false, x: 0.66, y: 0.56 },
  { giantId: 'mona', label: 'Мона', urgent: true, x: 0.8, y: 0.5 },
  { giantId: 'captain_duck', label: 'Уточка', urgent: false, x: 0.74, y: 0.72 },
] as const;

const pointByGiantId = new Map<GiantId, MapDeliveryPoint>(
  MAP_DELIVERY_POINTS.map((p) => [p.giantId, p]),
);

export function getMapDeliveryPoint(giantId: GiantId): MapDeliveryPoint {
  const p = pointByGiantId.get(giantId);
  if (p == null) {
    throw new Error(`No map point for giant: ${giantId}`);
  }
  return p;
}

export function tryGetMapDeliveryPoint(giantId: string): MapDeliveryPoint | null {
  return pointByGiantId.has(giantId as GiantId) ? getMapDeliveryPoint(giantId as GiantId) : null;
}

/** Каждый гигант ровно один раз на карте. */
export function assertMapCoversAllGiants(): void {
  if (MAP_DELIVERY_POINTS.length !== GIANT_IDS.length) {
    throw new Error(
      `Expected ${GIANT_IDS.length} map points, got ${MAP_DELIVERY_POINTS.length}`,
    );
  }
  for (const id of GIANT_IDS) {
    if (!pointByGiantId.has(id)) {
      throw new Error(`Map missing giant: ${id}`);
    }
  }
}

assertMapCoversAllGiants();
