import { NORM_LANE_PER_ROUTE_METER_S_REF, PLAYFIELD_WIDTH_M } from '../../domain';

/** Lane norm на 1 м маршрута S при заданном размере playfield (px). */
export function normLanePerRouteMeterS(
  playfieldWidthPx: number,
  playfieldHeightPx: number,
): number {
  return playfieldWidthPx / (PLAYFIELD_WIDTH_M * playfieldHeightPx);
}

function squareObstacleHitboxWithNormPerMeter(
  widthM: number,
  heightNorm: number,
  normPerMeter: number,
): { widthM: number; heightNorm: number } {
  const sizeNorm = Math.max(heightNorm, widthM * normPerMeter);
  return {
    widthM: sizeNorm / normPerMeter,
    heightNorm: sizeNorm,
  };
}

/** Квадратный AABB при эталонном playfield 9:16 (симуляция без размеров viewport). */
export function squareObstacleHitboxRef(
  widthM: number,
  heightNorm: number,
): { widthM: number; heightNorm: number } {
  return squareObstacleHitboxWithNormPerMeter(
    widthM,
    heightNorm,
    NORM_LANE_PER_ROUTE_METER_S_REF,
  );
}

/**
 * Квадратный AABB препятствия в world-координатах (S × lane norm).
 * Сторона = max(ширина по S, высота по lane) в экранных пикселях.
 */
export function squareObstacleHitbox(
  widthM: number,
  heightNorm: number,
  playfieldWidthPx: number,
  playfieldHeightPx: number,
): { widthM: number; heightNorm: number } {
  return squareObstacleHitboxWithNormPerMeter(
    widthM,
    heightNorm,
    normLanePerRouteMeterS(playfieldWidthPx, playfieldHeightPx),
  );
}

/** Квадратный хитбокс в пикселях playfield (для отрисовки отладки). */
export function squareObstacleHitboxPx(
  widthM: number,
  heightNorm: number,
  pxPerMeter: number,
  playfieldHeightPx: number,
  scale: number,
): { widthPx: number; heightPx: number } {
  const w = widthM * pxPerMeter * scale;
  const h = heightNorm * playfieldHeightPx * scale;
  const side = Math.max(w, h);
  return { widthPx: side, heightPx: side };
}
