import {
  BOOSTER_PICKUP_HEIGHT_NORM,
  BOOSTER_PICKUP_WIDTH_M,
  COLLISION_GRACE_SEC,
  COURIER_HITBOX_HEIGHT_NORM,
  COURIER_HITBOX_WIDTH_M,
  FLIGHT_BOOSTER_SCALE,
  FLIGHT_ENTITY_SCALE,
  FLIGHT_OBSTACLE_HITBOX_SCALE,
  getCourierRunStats,
  isTerminal,
  VERTICAL_SPEED_BASE_FACTOR,
} from '../../domain';
import { clampLaneCenterNorm } from './worldProjection';
import type { ModifierKind } from '../../domain';
import { getActiveModifierAtS } from './activeModifier';
import { aabbFromCenter, aabbIntersects } from './collision';
import { squareObstacleHitboxRef } from './obstacleHitbox';
import type { ObstacleInstance } from './expandObstacleSpawns';
import { buildObstacleInstancesFromLevel } from './expandObstacleSpawns';
import { FlightRunController } from './FlightRunController';
import type { GameSession } from './GameSession';
import { listLevelBoosterSpawnsSorted } from './levelBoosters';
import { listLevelSparkSpawnsSorted } from './levelSparks';
import { applyBoosterPickupToSession } from './boosterPickup';
import { clampCourierNormY, mapTapTargetNormY } from './modifierGameplay';

export type FlightWorldSnapshot = {
  courierY: number;
  courierS: number;
  activeModifier: ModifierKind | null;
  flashCourier: boolean;
  obstacles: readonly ObstacleInstance[];
  collectedSparkCount: number;
  totalSparkCount: number;
};

const SERGE_HYPNOSIS_DRIFT_PER_SEC = 0.045;
const SERGE_HYPNOSIS_POINTER_RESET_SEC = 0.35;

export class FlightWorldSimulation {
  readonly session: GameSession;

  readonly controller: FlightRunController;

  readonly obstacles: ObstacleInstance[];

  courierY = 0.5;

  targetY = 0.5;

  private readonly graceUntilByObstacleId = new Map<string, number>();

  private courierFlashUntil = 0;

  private readonly collectedBoosterKeys = new Set<string>();
  private readonly collectedSparkKeys = new Set<string>();

  private readonly boosterSpawns;
  private readonly sparkSpawns;

  private boosterSweepNeedsNegativeInfLow = true;
  private sparkSweepNeedsNegativeInfLow = true;

  private lastPointerActivitySec = 0;

  constructor(session: GameSession, controller?: FlightRunController) {
    this.session = session;
    this.controller =
      controller ??
      new FlightRunController(session, {
        pickupBoosters: false,
      });
    this.obstacles = buildObstacleInstancesFromLevel(session.level);
    this.boosterSpawns = listLevelBoosterSpawnsSorted(session.level);
    this.sparkSpawns = listLevelSparkSpawnsSorted(session.level);
  }

  setTargetY(normY: number): void {
    const mod = getActiveModifierAtS(this.session.level, this.controller.getDistanceAlongRouteS());
    this.targetY = mapTapTargetNormY(Math.min(1, Math.max(0, normY)), mod);
  }

  /** Сбрасывает «гипноз» Сержа при вводе игрока. */
  registerPointerActivity(): void {
    this.lastPointerActivitySec = this.session.getWorldTimeSec();
  }

  isBoosterCollected(segmentIndex: number, spawnIndex: number): boolean {
    return this.collectedBoosterKeys.has(`${segmentIndex}:${spawnIndex}`);
  }

  isSparkCollected(segmentIndex: number, spawnIndex: number): boolean {
    return this.collectedSparkKeys.has(`${segmentIndex}:${spawnIndex}`);
  }

  getSnapshot(): FlightWorldSnapshot {
    return {
      courierY: this.courierY,
      courierS: this.controller.getDistanceAlongRouteS(),
      activeModifier: getActiveModifierAtS(
        this.session.level,
        this.controller.getDistanceAlongRouteS(),
      ),
      flashCourier: this.session.getWorldTimeSec() < this.courierFlashUntil,
      obstacles: this.obstacles,
      collectedSparkCount: this.session.getCollectedSparkCount(),
      totalSparkCount: this.sparkSpawns.length,
    };
  }

  tickFrame(realDeltaSec: number): void {
    if (this.session.isMinigameGateActive() || isTerminal(this.session.getDeliveryRun())) {
      return;
    }

    const sBefore = this.controller.getDistanceAlongRouteS();
    this.controller.tickFrame(realDeltaSec);
    const sAfter = this.controller.getDistanceAlongRouteS();
    const dt = Math.min(0.25, Math.max(0, realDeltaSec));

    this.collectBoostersCrossed(sBefore, sAfter);
    this.collectSparksCrossed(sBefore, sAfter);
    this.applySergeHypnosis(dt, sAfter);
    this.updateVertical(dt, sAfter);
    this.updateObstaclePositions(dt);
    this.resolveCollisions(sAfter);
  }

  private collectBoostersCrossed(lowExclusive: number, highInclusive: number): void {
    const low = this.boosterSweepNeedsNegativeInfLow
      ? Number.NEGATIVE_INFINITY
      : lowExclusive;
    this.boosterSweepNeedsNegativeInfLow = false;
    for (const b of this.boosterSpawns) {
      const key = `${b.segmentIndex}:${b.spawnIndex}`;
      if (this.collectedBoosterKeys.has(key)) {
        continue;
      }
      if (b.s > low && b.s <= highInclusive) {
        const dx = Math.abs(b.s - highInclusive);
        const boosterLane = clampLaneCenterNorm(
          b.lane,
          (BOOSTER_PICKUP_HEIGHT_NORM * FLIGHT_BOOSTER_SCALE) / 2,
        );
        const dy = Math.abs(boosterLane - this.courierY);
        if (
          dx <= (BOOSTER_PICKUP_WIDTH_M * FLIGHT_BOOSTER_SCALE) / 2 &&
          dy <= (BOOSTER_PICKUP_HEIGHT_NORM * FLIGHT_BOOSTER_SCALE) / 2
        ) {
          this.collectedBoosterKeys.add(key);
          applyBoosterPickupToSession(this.session, b.type);
        }
      }
    }
    this.boosterSweepNeedsNegativeInfLow = false;
  }

  private collectSparksCrossed(lowExclusive: number, highInclusive: number): void {
    const low = this.sparkSweepNeedsNegativeInfLow ? Number.NEGATIVE_INFINITY : lowExclusive;
    this.sparkSweepNeedsNegativeInfLow = false;
    for (const spark of this.sparkSpawns) {
      const key = `${spark.segmentIndex}:${spark.spawnIndex}`;
      if (this.collectedSparkKeys.has(key)) {
        continue;
      }
      if (spark.s > low && spark.s <= highInclusive) {
        const dx = Math.abs(spark.s - highInclusive);
        const dy = Math.abs(spark.lane - this.courierY);
        if (
          dx <= (BOOSTER_PICKUP_WIDTH_M * FLIGHT_BOOSTER_SCALE) / 2 &&
          dy <= (BOOSTER_PICKUP_HEIGHT_NORM * FLIGHT_BOOSTER_SCALE) / 2
        ) {
          this.collectedSparkKeys.add(key);
          this.session.registerSparkPickup();
        }
      }
    }
  }

  private applySergeHypnosis(dt: number, courierS: number): void {
    const mod = getActiveModifierAtS(this.session.level, courierS);
    if (mod !== 'serge_hypnosis') {
      return;
    }
    const now = this.session.getWorldTimeSec();
    if (now - this.lastPointerActivitySec < SERGE_HYPNOSIS_POINTER_RESET_SEC) {
      return;
    }
    const towardCenter = 0.5 - this.courierY;
    this.courierY += Math.sign(towardCenter) * SERGE_HYPNOSIS_DRIFT_PER_SEC * dt;
  }

  private updateVertical(dt: number, courierS: number): void {
    const stats = getCourierRunStats(this.session.courierId);
    const maxSpeed = VERTICAL_SPEED_BASE_FACTOR * (stats.handling / 6);
    const diff = this.targetY - this.courierY;
    const step = maxSpeed * dt;
    if (Math.abs(diff) <= step) {
      this.courierY = this.targetY;
    } else {
      this.courierY += Math.sign(diff) * step;
    }
    const mod = getActiveModifierAtS(this.session.level, courierS);
    this.courierY = clampCourierNormY(this.courierY, mod);
  }

  private updateObstaclePositions(dt: number): void {
    for (const o of this.obstacles) {
      if (o.consumed) {
        continue;
      }
      if (o.motion === 'toward_player' && o.approachSpeedMps > 0) {
        o.worldS -= o.approachSpeedMps * dt;
      }
    }
  }

  private resolveCollisions(courierS: number): void {
    const shrink = this.session.getResizeShrinkHitboxMultiplier();
    const courierBox = aabbFromCenter(
      courierS,
      this.courierY,
      COURIER_HITBOX_WIDTH_M * FLIGHT_ENTITY_SCALE,
      COURIER_HITBOX_HEIGHT_NORM * FLIGHT_ENTITY_SCALE * shrink,
    );
    const now = this.session.getWorldTimeSec();

    for (const o of this.obstacles) {
      if (o.consumed) {
        continue;
      }
      if (o.worldS < courierS - 2 || o.worldS > courierS + 3) {
        continue;
      }
      const graceUntil = this.graceUntilByObstacleId.get(o.id);
      if (graceUntil != null && now < graceUntil) {
        continue;
      }
      const hitbox = squareObstacleHitboxRef(o.widthM, o.heightNorm);
      const obstacleBox = aabbFromCenter(
        o.worldS,
        o.lane,
        hitbox.widthM * FLIGHT_OBSTACLE_HITBOX_SCALE,
        hitbox.heightNorm * FLIGHT_OBSTACLE_HITBOX_SCALE,
      );
      if (!aabbIntersects(courierBox, obstacleBox)) {
        continue;
      }

      this.session.registerObstacleCollision();
      this.graceUntilByObstacleId.set(o.id, now + COLLISION_GRACE_SEC);
      this.courierFlashUntil = now + COLLISION_GRACE_SEC;
      o.consumed = true;
    }
  }
}
