import type { GiantId } from '../ids/ids';
import type { ModifierKind } from './modifiers';

/**
 * Модификатор уровня по гиганту (GDD, один на уровень).
 * Для Дракочи вместо удалённого `boiling_lake_heat` — `foam_fog`.
 */
export const GIANT_LEVEL_MODIFIER: Record<GiantId, ModifierKind> = {
  swami: 'swami_leaf_overlay',
  rose_observatory: 'starfall',
  drakocha: 'foam_fog',
  yeti: 'yeti_icicle_corridor',
  mona: 'wave_surge',
  captain_duck: 'screen_shake',
  serge: 'serge_hypnosis',
  factor: 'factor_mirage',
  sol: 'solar_ray',
  luna_mu: 'proximity_visibility',
  haunted_house: 'inverted_controls',
  uncle_willy: 'willy_blur',
};

export function getModifierForGiant(giantId: GiantId): ModifierKind {
  return GIANT_LEVEL_MODIFIER[giantId];
}
