import type { DeliveryOutcome } from './delivery';

/**
 * Состояние одной попытки доставки (жизни + мини-игра по GDD).
 * Симуляция решает, засчитывается ли столкновение (например, при активной «Защите» — не вызывать этот переход).
 */
export type DeliveryRunState =
  | { kind: 'flying'; strikesTowardMinigame: number }
  | { kind: 'minigame_required' }
  | { kind: 'terminal'; outcome: DeliveryOutcome };

export type CountedCollisionResult = {
  state: DeliveryRunState;
  /** Исчерпан буфер жизней — нужно открыть мини-игру курьера. */
  openedMinigame: boolean;
};

function assertFlyingStrikesInvariant(
  strikes: number,
  collisionsBeforeMinigame: number,
): void {
  if (strikes < 0 || strikes >= collisionsBeforeMinigame) {
    throw new Error(
      `Invariant: strikesTowardMinigame must be in [0, ${collisionsBeforeMinigame}), got ${strikes}`,
    );
  }
}

export function createInitialDeliveryRun(): DeliveryRunState {
  return { kind: 'flying', strikesTowardMinigame: 0 };
}

/**
 * Засчитать столкновение с препятствием (уже с учётом бустеров в вызывающем коде).
 */
export function applyCountedObstacleCollision(
  state: DeliveryRunState,
  collisionsBeforeMinigame: number,
): CountedCollisionResult {
  if (state.kind === 'terminal') {
    return { state, openedMinigame: false };
  }
  if (state.kind === 'minigame_required') {
    return { state, openedMinigame: false };
  }

  if (!Number.isInteger(collisionsBeforeMinigame) || collisionsBeforeMinigame < 1) {
    throw new Error(
      `applyCountedObstacleCollision: collisionsBeforeMinigame must be a positive integer, got ${collisionsBeforeMinigame}`,
    );
  }

  assertFlyingStrikesInvariant(state.strikesTowardMinigame, collisionsBeforeMinigame);

  const next = state.strikesTowardMinigame + 1;
  if (next >= collisionsBeforeMinigame) {
    return { state: { kind: 'minigame_required' }, openedMinigame: true };
  }
  return {
    state: { kind: 'flying', strikesTowardMinigame: next },
    openedMinigame: false,
  };
}

/** Победа в мини-игре: сброс счётчика столкновений (GDD). */
export function resolveMinigameWin(state: DeliveryRunState): DeliveryRunState {
  if (state.kind !== 'minigame_required') {
    return state;
  }
  return { kind: 'flying', strikesTowardMinigame: 0 };
}

/** Поражение в мини-игре: доставка провалена (GDD). */
export function resolveMinigameLoss(state: DeliveryRunState): DeliveryRunState {
  if (state.kind !== 'minigame_required') {
    return state;
  }
  return { kind: 'terminal', outcome: 'failed_minigame' };
}

/** Игрок вышел / отмена попытки. */
export function abortDeliveryRun(state: DeliveryRunState): DeliveryRunState {
  if (state.kind === 'terminal') {
    return state;
  }
  return { kind: 'terminal', outcome: 'aborted' };
}

/** Успешное завершение уровня (доставка завершена). */
export function completeDeliveryRun(state: DeliveryRunState): DeliveryRunState {
  if (state.kind === 'terminal') {
    return state;
  }
  return { kind: 'terminal', outcome: 'completed' };
}

/**
 * Оставшиеся «жизни» до мини-игры: буфер столкновений + заряды доп. жизни.
 */
export function getRemainingLivesForHud(
  state: DeliveryRunState,
  extraLifeCharges: number,
  maxLivesBeforeMinigame: number,
): number {
  if (state.kind === 'terminal') {
    return 0;
  }
  const strikeBuffer =
    state.kind === 'flying'
      ? maxLivesBeforeMinigame - state.strikesTowardMinigame
      : 0;
  return strikeBuffer + Math.max(0, extraLifeCharges);
}

/**
 * Ступень «потрёпанности» визуала курьера (GDD: 3 версии по мере убывания жизней).
 * До порога мини-игры: 0 ударов — целый, 1 — лёгкий, 2+ — сильный износ; в ожидании мини-игры — максимальная ступень.
 */
export function getStrikeDamageVisualStage(state: DeliveryRunState): 0 | 1 | 2 | null {
  if (state.kind === 'terminal') {
    return null;
  }
  if (state.kind === 'minigame_required') {
    return 2;
  }
  if (state.strikesTowardMinigame <= 0) {
    return 0;
  }
  if (state.strikesTowardMinigame === 1) {
    return 1;
  }
  return 2;
}

export function isTerminal(state: DeliveryRunState): boolean {
  return state.kind === 'terminal';
}

export function getTerminalOutcome(state: DeliveryRunState): DeliveryOutcome | null {
  return state.kind === 'terminal' ? state.outcome : null;
}
